(window.NTDATA=window.NTDATA||{});(NTDATA.cass=NTDATA.cass||{}).acts={"1":{"1":"Первую книгу, Феофил, составил я о всём, что с\nсамого начала делал и чему учил Иисус,","2":"до того дня, когда Он был вознесён, дав Духом\nСвятым повеления апостолам, которых Он избрал,","3":"которым Он и показал Себя живым, по страдании\nСвоем, со многими доказательствами, сорок дней\nявляясь им и говоря о Царстве Божием.","4":"И, за трапезою, Он повелел им не отлучаться из\nИерусалима, но ждать обещанного Отцом: о чем вы\nслышали от Меня.","5":"Ибо Иоанн крестил водою, вы же будете крещены\nДухом Святым, по истечении немногих этих дней.","6":"Итак, собравшись вместе, они спрашивали Его:\nГосподи, не в это ли время восстанавливаешь Ты\nЦарство Израилю?","7":"И Он сказал им: не вам знать времена и сроки,\nкоторые Отец установил Своею властью.","8":"Но вы примете силу, когда найдет Святой Дух на\nвас, и вы будете Моими свидетелями и в Иерусалиме, и\nво всей Иудее и Самарии, и до предела земли.","9":"И сказав это – пока они смотрели – Он был поднят,\nи облако скрыло Его из глаз их.","10":"И как взоры их были устремлены к небу, во время\nЕго отшествия, вот два мужа предстали им в одеяниях\nбелых,","11":"и сказали: мужи Галилейские, что вы стоите,\nглядя на небо? Этот Иисус, вознесённый от вас на небо,\nпридет\nтаким\nже\nобразом,\nкак\nвы\nвидели\nЕго\nотходящим на небо.","12":"Тогда возвратились они в Иерусалим с горы,\nназываемой Елеон, которая находится близ Иерусалима\nв расстоянии субботнего пути.","13":"И когда они вошли, то поднялись в горницу, где\nпребывали, как Петр так и Иоанн, и Иаков и Андрей,\nФилипп и Фома, Варфоломей и Матфей, Иаков Алфеев и\nСимон Зилот, и Иуда Иаковлев.","14":"Все они были единодушны в постоянной молитве\nс женщинами и с Мариам, Матерью Иисуса, и с братьями\nЕго.","15":"В эти дни, встав посреди братьев, Петр сказал (а\nсобравшихся в большом числе было около ста двадцати\nчеловек):","16":"Мужи братья, надлежало исполниться Писанию,\nв котором Дух Святой предсказал устами Давида об\nИуде, ставшем проводником для взявших Иисуса,","17":"потому что он был сопричислен к нам и получил\nжребий этого служения.","18":"(Он приобрел землю из цены злодеяния и, упав\nголовой вниз, расселся, и выпали все внутренности его.","19":"И стало это известным всем живущим в\nИерусалиме,\nтак\nчто\nземля\nта\nназвана\nна\nих\nсобственном наречии Акелдама, то есть земля крови).","20":"Ибо написано в книге Псалмов: «Да будет двор\nего пуст, и да не будет живущего в нем», и: «должность\nего да примет иной».","21":"Итак, надлежит, чтобы один из мужей, вместе с\nнами ходивших всё то время, когда жил среди нас\nГосподь Иисус,","22":"начиная от крещения Иоаннова до того дня,\nкогда Он был вознесён от нас, – стал вместе с нами\nсвидетелем воскресения Его.","23":"И\nпоставили\nдвоих:\nИосифа,\nназываемого\nВарсавой, который был прозван Иустом, и Матфия.","24":"И\nпомолились\nи\nсказали:\nТы,\nГосподи,\nСердцеведец всех, покажи, кого Ты избрал, из этих двух\nодного,","25":"принять место этого служения и апостольства, от\nкоторого отпал Иуда, чтобы пойти в свое место.","26":"И дали им жребии. И пал жребий на Матфия, и он\nбыл сопричислен к одиннадцати апостолам."},"2":{"1":"И когда подходил к концу день Пятидесятницы,\nбыли они все вместе.","2":"И вдруг раздался с неба шум, как бы от\nнесущегося сильного ветра, и наполнил весь дом, где\nони находились,","3":"и явились им разделяющиеся языки, как бы\nогненные, и почили по одному на каждом из них.","4":"И исполнились все Духа Святого и начали\nговорить иными языками, как Дух давал им вещать.","5":"Жили в Иерусалиме Иудеи, благоговейные люди\nиз всякого народа под небом.","6":"Когда же прошел об этом слух, собралось много\nлюдей и пришли в смятение, потому что каждый из них\nслышал, как они говорили на его собственном наречии.","7":"Изумлялись все и дивились, говоря: вот все эти\nговорящие, разве они не Галилеяне?","8":"Как же мы их слышим каждый на своем\nсобственном наречии, в котором мы родились:","9":"Парфяне, и Мидяне, и Эламиты, и живущие в\nМесопотамии, в Иудее и Каппадокии, Понте и Асии,","10":"Фригии и Памфилии, в Египте и в частях Ливии,\nпримыкающих к Киринее, и пришедшие из Рима, как\nИудеи, так и прозелиты,","11":"Критяне и Арабы – слышим, как они говорят на\nнаших языках о великих делах Божиих?","12":"И все изумлялись и недоумевали, говоря друг\nдругу: что бы это могло быть?","13":"А иные издеваясь говорили: они напились\nсладкого вина.","14":"Петр же, став с одиннадцатью, возвысил свой\nголос и возгласил им: мужи Иудейские и все, живущие в\nИерусалиме! Да будет вам это известно и вслушайтесь в\nслова мои.","15":"Ибо не пьяны они, как вы предполагаете: ведь\nтолько третий час дня.","16":"Но это то, что сказано чрез пророка Иоиля:","17":"«И будет в последние дни, говорит Бог: изолью\nот\nДуха\nМоего\nна\nвсякую\nплоть,\nи\nбудут\nпророчествовать сыны ваши и дочери ваши, и юноши\nваши будут видеть видения. И старцам вашим будут\nсниться сны,","18":"и на рабов Моих и на рабынь Моих в те дни\nизолью от Духа Моего, и будут пророчествовать.","19":"И дам чудеса на небе вверху и знамения на\nземле внизу, кровь и огонь и клубы дыма.","20":"Солнце превратится в тьму, и луна в кровь,\nпрежде\nчем\nпридет\nдень\nГосподень\nвеликий\nи\nблистающий.","21":"И будет: всякий, кто призовет имя Господне,\nбудет спасен».","22":"Мужи Израильские! Выслушайте эти слова:\nИисуса Назорея, Мужа, Богом отмеченного для вас\nсилами, и чудесами, и знамениями, которые сотворил\nчрез Него Бог среди вас, как вы сами знаете,","23":"Его, по определению и предведению Божию\nпреданного, вы, пригвоздив рукою беззаконных, убили.","24":"Бог Его воскресил, разрешив муки смерти,\nпотому что Он не мог быть держим ею.","25":"Ибо Давид говорит о Нем: «Я видел Господа\nпредо мною непрестанно, ибо Он по правую мою\nсторону, дабы я не поколебался.","26":"Оттого возрадовалось мое сердце и возликовал\nязык мой, даже и плоть моя пребудет в надежде,","27":"ибо Ты не оставишь души моей во аде и не дашь\nсвятому Твоему увидеть тление.","28":"Ты поведал мне пути жизни, Ты исполнишь меня\nрадости пред лицом Твоим».","29":"Мужи братья! Да позволено будет сказать вам с\nдерзновением о патриархе Давиде, что он и скончался и\nпогребен, и гробница его у нас до сего дня.","30":"Итак, будучи пророком и зная, что клятвою\nпоклялся ему Бог от плода чресл его посадить на\nпрестоле его,","31":"– он, провидя, изрек о воскресении Христа, что и\nОн не оставлен во аде, и плоть Его не увидела тления.","32":"Этого Иисуса воскресил Бог, чему все мы\nсвидетели.","33":"Итак, десницей Божией вознесённый, и приняв\nот Отца обещанного Духа Святого, Он излил то, что вы и\nвидите и слышите.","34":"Ибо Давид не восшел на небеса, но он сам\nговорит: «Сказал Господь Господу Моему: сядь по\nправую сторону Мою,","35":"доколе Я не положу врагов Твоих в подножие ног\nТвоих».","36":"Итак, твердо знай весь дом Израилев, что и\nГосподом и Христом сделал Его Бог, Того Иисуса,\nКоторого вы распяли.","37":"Они же, услышав, поражены были в самое\nсердце, и сказали Петру и остальным апостолам: что\nнам делать, мужи братья?","38":"А Петр им сказал: покайтесь, и да крестится\nкаждый из вас во имя Иисуса Христа для отпущения\nгрехов ваших, и вы получите дар Святого Духа.","39":"Ибо для вас обещание и для детей ваших и для\nвсех дальних, кого ни призовет Господь Бог наш.","40":"И иными многими словами он свидетельствовал и\nувещал их, говоря: спасайтесь от этого извращенного\nрода.","41":"Итак, приняв слово его, они были крещены. И\nприсоединилось в день тот душ около трех тысяч.","42":"И пребывали они постоянно в учении апостолов и\nв общении, в преломлении хлеба и в молитвах.","43":"Был же во всякой душе страх. И много чудес и\nзнамений совершалось чрез апостолов.","44":"А все уверовавшие были вместе и всё у них было\nобщее.","45":"И то, чем владели и что имели, они продавали и\nразделяли это всем, смотря по нужде каждого.","46":"И каждый день единодушно пребывая в храме, и\nпреломляя по домам хлеб, они принимали пищу в\nвеселии и простоте сердца,","47":"хваля Бога и будучи в милости у всего народа. А\nГосподь прибавлял к ним спасаемых каждый день."},"3":{"1":"Петр же и Иоанн поднимались в храм в час\nмолитвы – девятый.","2":"И был некий человек, хромой от чрева матери его,\nкоторого приносили и сажали ежедневно у ворот храма,\nназываемых Красными, просить милостыню у входящих\nв храм.","3":"Увидев, что Петр и Иоанн собираются войти в\nхрам, он стал просить милостыню.","4":"Петр же вместе с Иоанном, устремив на него\nвзгляд, сказал: посмотри на нас.","5":"И тот стал пристально глядеть на них, ожидая\nчто-нибудь от них получить.","6":"И сказал Петр: серебра и золота нет у меня. А что\nимею, то даю тебе: во имя Иисуса Христа Назорея, ходи.","7":"И взяв его за правую руку, поднял его. И тотчас\nукрепились ступни его и суставы,","8":"и, вскочив, он стал на ноги и начал ходить и вошел\nс ними в храм, ходя и скача и хваля Бога.","9":"И увидел его весь народ ходящим и хвалящим\nБога.","10":"И узнавали его, что это сидевший для милостыни\nу Красных ворот храма. И исполнились ужаса и\nизумления от случившегося с ним.","11":"А так как он не отходил от Петра и Иоанна, то\nсбежался к ним в трепете весь народ в притворе\nназываемом Соломоновым.","12":"Увидев\nже,\nПетр\nответил\nнароду:\nМужи\nИзраильские, что вы удивляетесь этому? Или на нас что\nсмотрите,\nкак\nбудто\nмы\nсобственной\nсилой\nили\nблагочестием сделали так, что он ходит.","13":"Бог Авраама и Исаака и Иакова, Бог отцов наших,\nпрославил Отрока Своего Иисуса, Которого вы предали\nи от Которого отреклись пред лицом Пилата, когда тот\nрешил отпустить Его.","14":"Вы же от Святого и Праведного отреклись и\nвыпросили себе, как милость, человека убийцу,","15":"а Начальника жизни убили, Его, Которого Бог\nвоздвиг из мертвых, чему мы свидетели.","16":"И по вере во имя Его, укрепило имя Его того, кого\nвы видите и знаете. И вера, которая чрез Него, дала ему\nэто совершенное здравие перед всеми вами.","17":"И теперь, братья, знаю, что вы поступили по\nневедению, как и начальники ваши.","18":"Бог же, как предвозвестил устами всех пророков\nпострадать Христу Его, так и исполнил.","19":"Итак покайтесь и обратитесь, чтобы изглажены\nбыли ваши грехи,","20":"чтобы пришли времена прохлады от лица\nГоспода и чтобы послал Он предназначенного вам\nХриста Иисуса,","21":"Которого небо должно принять до времен\nвосстановления всего, о чем изрек Бог устами святых\nдревних Своих пророков.","22":"А Моисей сказал: «Пророка вам воздвигнет\nГосподь\nБог\nиз\nбратьев\nваших,\nкак\nменя.\nЕго\nслушайтесь во всём, что Он скажет вам.","23":"Будет же: всякая душа, которая не послушает\nПророка Того, истребится из народа».","24":"Да и все пророки от Самуила и после него, те,\nкоторые изрекли слово, они возвестили эти дни.","25":"Вы сыны пророков и завета, который Бог завещал\nотцам нашим, говоря Аврааму: «и в семени твоем\nблагословятся все племена земные».","26":"Бог, воскресив Отрока Своего, к вам первым\nпослал Его, благословляющего вас, чтобы каждого\nотвратить от злых дел ваших."},"4":{"1":"А пока они говорили к народу, приступили к ним\nсвященники и начальник храмовой стражи и саддукеи,","2":"досадуя на то, что они учат народ и возвещают в\nИисусе воскресение из мертвых,","3":"и наложили на них руки и отдали под стражу до\nследующего дня, ибо был уже вечер.","4":"Многие же из слышавших слово уверовали. И\nдостигло число мужей тысяч до пяти.","5":"И было на следующий день, что собрались в\nИерусалиме начальники их и старейшины и книжники,","6":"и Анна первосвященник и Каиафа, и Иоанн и\nАлександр, и все, кто были из первосвященнического\nрода,","7":"и, поставив их посредине, допрашивали: какой\nсилой или каким именем вы это сделали?","8":"Тогда Петр, исполнившись Духа Святого, сказал\nим: начальники народа и старейшины,","9":"если нам сегодня чинят допрос о благодеянии\nчеловеку больному, каким образом он спасен,","10":"то да будет известно вам и всему народу\nИзраильскому, что именем Иисуса Христа Назорея,\nКоторого вы распяли, Которого Бог воздвиг из мертвых,\n– Им стоит он перед вами здоровый.","11":"Он есть Камень, признанный негодным вами –\nстроителями, оказавшийся во главе угла.","12":"И нет ни в ком другом спасения. Ибо под небом\nнет и иного имени, данного людям, которым надлежит\nнам быть спасенными.","13":"Видя же дерзновение Петра и Иоанна, и поняв,\nчто они люди некнижные и простецы, удивлялись и\nпризнавали их, что они были с Иисусом.","14":"И видя, что человек, исцеленный, с ними стоит,\nничего не могли возразить.","15":"И, приказав им выйти вон из синедриона,\nсовещались друг с другом","16":"и говорили: что нам делать с этими людьми?\nВедь то, что ими совершено замечательное знамение,\nэто явно всем живущим в Иерусалиме, и мы не можем\nотрицать;","17":"но, чтобы оно еще больше не распространилось в\nнароде, пригрозим им, чтобы они уже от этого имени не\nговорили никому из людей.","18":"И, призвав их, приказали совсем не говорить и не\nучить во имя Иисуса.","19":"Но Петр и Иоанн сказали им в ответ: рассудите,\nсправедливо ли пред Богом, слушать вас больше чем\nБога?","20":"Ибо не можем мы не говорить о том, что видели и\nслышали.","21":"И, снова пригрозив, отпустили их, так и не\nнаходя повода наказать их, из-за народа, потому что\nвсе прославляли Бога за происшедшее.","22":"Ибо больше сорока лет было тому человеку, над\nкоторым произошло это знамение исцеления.","23":"Будучи отпущены, они пришли к своим и\nсообщили им всё, что им сказали первосвященники и\nстарейшины.","24":"Они же, выслушав, возвысили голос к Богу и\nсказали: Владыко, Ты, сотворивший небо и землю, и\nморе, и всё, что в них,","25":"сказавший чрез Духа Святого, устами отца\nнашего Давида, отрока Твоего: «Почему разъярились\nязычники, и народы замыслили праздное?","26":"Предстали цари земные, и начальники собрались\nвместе против Господа и против Помазанника Его».","27":"Собрались, ведь, воистину в городе этом на\nСвятого Отрока Твоего Иисуса, Которого Ты помазал,\nИрод и Понтий Пилат с язычниками и народами\nИзраиля,","28":"чтобы сделать то, чему предопределила быть\nТвоя рука и совет.","29":"И теперь, Господи, взгляни на угрозы их и дай\nрабам Твоим со всяким дерзновением говорить слово\nТвое,","30":"простирая руку Твою так, чтобы были исцеления,\nзнамения и чудеса именем Святого Отрока Твоего\nИисуса.","31":"И когда они помолились, поколебалось место,\nгде они были собраны, и исполнились все Святого Духа\nи говорили слово Божие с дерзновением.","32":"Было же у множества уверовавших сердце и\nдуша одна. И никто ничего из имения своего не называл\nсобственным, но было у них всё общее.","33":"И с великою силой свидетельствовали апостолы\nо воскресении Господа Иисуса, и благодать великая\nбыла на всех их.","34":"Ибо не было и никого нуждающегося между\nними. А все, кто были собственниками земель или\nдомов, продавая, приносили цену продаваемого","35":"и полагали у ног апостолов. И раздавалось\nкаждому смотря по нужде его.","36":"Иосиф же, прозванный апостолами Варнавой, что\nв переводе значит «сын утешения», левит, родом\nКипрянин,","37":"так как у него была земля, продав, принес\nденьги и положил к ногам апостолов."},"5":{"1":"А некий муж, по имени Анания, с Сапфирой, женой\nсвоей, продал имение,","2":"и часть цены утаил с ведома и жены; и принеся\nнекую долю, положил у ног апостолов,","3":"Но Петр сказал: Анания, почему это наполнил\nсатана сердце твое, что ты солгал Духу Святому и утаил\nот цены земли?","4":"Оставаясь\nнепроданной,\nне\nтвоей\nли\nона\nоставалась? И вырученное продажей не в твоей ли\nвласти было? Как это положил ты в сердце своем такое\nдело? Не людям ты солгал, но Богу.","5":"При этих словах Анания упал и испустил дух. И\nнашел страх великий на всех слышавших.","6":"И молодые, встав, приготовили его к погребению,\nи, вынося, похоронили.","7":"И было, часа через три: вошла и жена его, не\nзнавшая о происшедшем.","8":"И обратился к ней Петр: скажи мне: за столько ли\nвы продали землю? и она сказала: да, за столько.","9":"И Петр к ней: что это вы согласились искусить\nДуха Господня? Вот ноги похоронивших мужа твоего в\nдверях, и они вынесут тебя.","10":"И упала она тотчас к ногам его и испустила дух.\nВойдя же, юноши нашли ее мертвой, и, вынеся,\nпохоронили около мужа ее.","11":"И нашел страх великий на всю церковь и на всех\nслышавших об этом.","12":"Руками же апостолов совершались многие\nзнамения и чудеса в народе. И были все единодушно в\nпритворе Соломоновом.","13":"Из прочих же никто не осмеливался примыкать к\nним. Но их прославлял народ.","14":"И всё больше прибавлялось верующих в Господа,\nмножество мужчин и женщин,","15":"так что и на улицы выносили больных и клали на\nносилках и кроватях, чтобы, когда Петр проходил, хотя\nбы тень его осенила кого-нибудь из них.","16":"Сходилось и множество народа из городов\nвокруг Иерусалима, неся больных и нечистыми духами\nодержимых, которые исцелялись все.","17":"Тогда поднялся первосвященник, и все, кто были\nс ним из толка саддукейского, исполнились ревности,","18":"и наложили на апостолов руки и посадили их в\nобщую тюрьму.","19":"Но ангел Господень ночью отворил двери\nтюрьмы и, выведя их, сказал:","20":"идите, станьте и говорите в храме народу все\nслова жизни этой.","21":"И они, услышав, вошли под утро в храм и стали\nучить. Но, прибыв, первосвященник и те, кто были с\nним, созвали синедрион и весь совет старейшин сынов\nИзраилевых и послали в тюрьму привести их.","22":"Но пришедшие служители не нашли их в тюрьме.\nИ, возвратившись, донесли,","23":"говоря: мы нашли, что тюрьма заперта со\nвсяческой предосторожностью, и что сторожа стоят у\nдверей, но открыв, мы внутри не нашли никого.","24":"Когда\nи\nначальник\nхрамовой\nстражи\nи\nпервосвященники\nуслышали\nэти\nслова,\nони\nнедоумевали о них: что бы это могло быть?","25":"Но пришел кто-то и сообщил им: вот мужи,\nкоторых вы посадили в тюрьму, стоят в храме и учат\nнарод.","26":"Тогда пошел начальник стражи со служителями\nи привел их без принуждения, ибо боялись народа, как\nбы не быть побитыми камнями.","27":"И приведя их, поставили в синедрионе. И спросил\nих первосвященник:","28":"мы строжайше приказали вам не учить от этого\nимени. И вот, вы наполнили Иерусалим учением вашим\nи хотите навести на нас кровь Этого Человека.","29":"Но Петр и апостолы сказали: повиноваться\nдолжно Богу больше чем людям,","30":"Бог отцов наших воздвиг Иисуса, Которого вы\nумертвили, повесив на древе:","31":"Его Бог вознес десницей Своей, как Начальника и\nСпасителя, чтобы дать Израилю покаяние и отпущение\nгрехов.","32":"И мы свидетели тому, и Дух Святой, Которого Бог\nдал повинующимся Ему.","33":"Слышавшие были в бешенстве и хотели убить их.","34":"Встал тогда член синедриона – фарисей, по\nимени\nГамалиил,\nзаконоучитель,\nпочитаемый\nвсем\nнародом, и приказал вывести этих людей ненадолго.","35":"А\nим\nсказал:\nмужи\nИзраильские,\nбудьте\nосторожны с этими людьми. Что вы хотите делать?","36":"Ведь перед этими днями явился Февда, выдавая\nсебя за кого-то. К нему примкнуло около четырехсот\nчеловек. Он был убит, и все, кто следовали за ним, были\nрассеяны и обратились в ничто.","37":"После него явился Иуда Галилеянин в дни\nпереписи и увлек народ за собой. Погиб и он, и все, кто\nследовали за ним, рассыпались.","38":"И теперь говорю вам, отстаньте от этих людей и\nпустите их. Ибо если от людей начинание это или дело\nэто, – оно будет разрушено.","39":"А если от Бога, то вы не сможете одолеть их. Как\nбы\nвам\nне\nоказаться\nи\nбогоборцами.\nОни\nего\nпослушались.","40":"И призвав апостолов, подвергли их бичеванию,\nприказали не говорить от имени Иисуса и отпустили.","41":"И уходили они из синедриона, радуясь, что были\nудостоены понести бесчестие за Имя.","42":"И каждый день в храме и по домам не\nпереставали учить и благовествовать Христа Иисуса."},"6":{"1":"В эти дни, когда умножалось число учеников,\nвозник ропот у еллинистов на евреев за то, что вдовы\nих были пренебрегаемы в ежедневном обслуживании.","2":"Тогда Двенадцать, созвав собрание всех учеников,\nсказали: не приличествует нам, оставив слово Божие,\nобслуживать столы,","3":"Отберите же, братья, из своей среды семь мужей,\nимеющих\nдоброе\nсвидетельство,\nполных\nДуха\nи\nмудрости. Им поручим эту службу.","4":"Мы же будем постоянно пребывать в молитве и\nслужении слова.","5":"И угодно было предложение всему собранию. И\nони избрали Стефана, мужа полного веры и Духа\nСвятого, и Филиппа, и Прохора, и Никанора, и Тимона, и\nПармена, и Николая, прозелита Антиохийца.","6":"Их\nпоставили\nперед\nапостолами,\nи\nте,\nпомолившись, возложили на них руки.","7":"И слово Божие росло, и сильно умножалось число\nучеников в Иерусалиме, и очень много священников\nподчинялось вере.","8":"Стефан же, полный благодати и силы, творил\nчудеса и знамения великие в народе.","9":"И восстали некоторые из входивших в синагогу,\nназываемую синагогой либертинцев, киринейцев и\nалександрийцев и из тех, что были из Киликии и Асии;\nспоря со Стефаном,","10":"они не могли противостать мудрости и Духу,\nКоторым он говорил.","11":"Тогда они подослали людей, говоривших: мы\nслышали, как он говорил слова хулы на Моисея и на\nБога.","12":"И они привели в движение народ и старейшин и\nкнижников, и напав, схватили его и повели в синедрион.","13":"И выставили ложных свидетелей, говоривших:\nэтот человек не перестает говорить слова против\nсвятого места этого и Закона.","14":"Ибо мы слышали, как он говорил, что этот Иисус\nНазорей разрушит место это и переменит те обычаи,\nкоторые предал нам Моисей.","15":"И устремив на него взгляд, все сидящие в\nсинедрионе увидели лицо его, как лицо ангела."},"7":{"1":"И сказал первосвященник: так ли это?","2":"И тот сказал: Мужи братья и отцы! Послушайте!\nБог славы явился отцу нашему Аврааму, когда он был\nеще в Месопотамии, прежде поселения его в Харране, и\nсказал ему:","3":"«выйди из земли твоей и из родни твоей и иди в\nземлю, которую Я тебе укажу».","4":"Тогда, выйдя из земли Халдейской, поселился он в\nХарране. И оттуда, по смерти отца его, Бог переселил\nего в эту землю, на которой вы теперь живете.","5":"И не дал ему наследия в ней ни на стопу ноги, но\nобещал дать ее во владение ему и семени его после\nнего, обещал, когда не было у него детей.","6":"И Бог сказал так: «будет семя его пришельцем на\nземле чужой, и поработят его и будут творить ему зло\nчетыреста лет.","7":"И народ, которому они будут рабами, судить буду\nЯ» – Бог сказал, – «и после этого они выйдут и будут\nслужить Мне на этом месте».","8":"И дал ему завет обрезания. И так родил он Исаака\nи обрезал его в день восьмой; и Исаак – Иакова, и Иаков\n– двенадцать патриархов.","9":"И патриархи, позавидовав Иосифу, продали его в\nЕгипет. И был Бог с ним,","10":"и избавил его от всех скорбей и дал ему милость\nи мудрость в глазах фараона, царя Египетского. И\nпоставил его начальником над Египтом и над всем\nдомом его.","11":"И пришел голод на весь Египет и Ханаан, и\nскорбь великая; и не находили пищи отцы наши.","12":"Иаков же, услышав, что есть хлеб в Египте,\nпослал отцов наших в первый раз.","13":"И во второй раз узнан был Иосиф братьями\nсвоими, и стал известен фараону род Иосифа.","14":"Иосиф же послал и вызвал Иакова, отца своего, и\nвсю родню: семьдесят пять душ.","15":"И сошел Иаков в Египет и скончался сам и отцы\nнаши;","16":"и были они перенесены в Сихем и положены в\nгробнице, которую купил Авраам ценой серебра у сынов\nЕмморовых в Сихеме.","17":"Когда\nже\nстало\nприближаться\nвремя\nисполниться обещанию, которое Богу угодно было дать\nАврааму, возрос народ и умножился в Египте.","18":"Так было, пока не восстал иной царь над\nЕгиптом, который не знал Иосифа.","19":"Он, прибегнув к хитрости против рода нашего, в\nзлобе на отцов, заставлял их бросать младенцев своих,\nчтобы те не оставались в живых.","20":"В это время родился Моисей и был прекрасен\nпред Богом. Его кормили три месяца в доме отца.","21":"А когда был он брошен, взяла его к себе дочь\nфараона и воспитала его как своего сына.","22":"И научен был Моисей всей мудрости Египетской\nи был силен в словах и делах своих.","23":"Когда же исполнялось ему сорок лет, пришло\nему\nна\nсердце\nпосетить\nбратьев\nсвоих,\nсынов\nИзраилевых.","24":"И увидев, что кого-то обижают, он заступился и\nотомстил за страдавшего, поразив Египтянина.","25":"Он думал, что братья понимают, что Бог рукой\nего дает спасение им; но они не поняли.","26":"На следующий день он появился между ними,\nкогда они дрались, и склонял их к миру словами: «мужи,\nвы – братья; почему вы обижаете друг друга?»","27":"Но обижающий ближнего оттолкнул его, сказав:\n«кто тебя поставил начальником и судьей над нами?","28":"Не хочешь ли ты убить меня так же, как убил\nвчера Египтянина?»","29":"И бежал Моисей из-за этого слова и стал\nпришельцем в земле Мадиамской, где он родил двух\nсыновей,","30":"И по исполнении сорока лет, явился ему в\nпустыне горы Синая Ангел в пламени горящей купины.","31":"Моисей же, увидев, дивился видению. А когда он\nподходил, чтобы всмотреться, раздался голос Господа:","32":"«Я – Бог отцов твоих, Бог Авраама, и Исаака, и\nИакова».\nОбъятый\nтрепетом,\nМоисей\nне\nпосмел\nвсматриваться,","33":"И сказал ему Господь: «сними обувь с ног твоих,\nибо место, на котором ты стоишь, земля святая.","34":"Увидел Я, увидел притеснение народа Моего,\nкоторый в Египте, и стенание его услышал и нисшел\nосвободить их. И теперь иди, Я пошлю тебя в Египет».","35":"Этого Моисея, которого они отвергли, сказав:\n«кто тебя поставил начальником и судьей?» – его-то\nпослал Бог и начальником и избавителем, рукою Ангела,\nявившегося ему в купине.","36":"Это он вывел их, творя чудеса и знамения в\nземле Египетской и в Чермном море и в пустыне сорок\nлет.","37":"Это\nтот\nМоисей,\nкоторый\nсказал\nсынам\nИзраилевым: «Пророка вам воздвигнет Бог из братьев\nваших, как меня».","38":"Это тот, кто в собрании в пустыне был с Ангелом,\nговорившим ему на горе Синае, и с отцами нашими; тот,\nкоторый принял слова живые, чтобы дать вам,","39":"которому не захотели покориться отцы ваши, но\nотринули его и обратились сердцами своими к Египту,","40":"сказав Аарону: «сделай нам богов, которые\nпойдут впереди нас, ибо Моисей этот, который вывел\nнас из земли Египетской, – не знаем, что случилось с\nним».","41":"И сделали они тельца в дни те, и принесли\nжертву идолу, и радовались делу рук своих.","42":"И отвратился Бог и предал их служить воинству\nнебесному, как написано в книге Пророков: «Заклания и\nжертвы принесли ли вы Мне за сорок лет в пустыне, дом\nИзраилев?","43":"И взяли вы с собою скинию Молоха и звезду бога\nвашего Ремфана, изображения, которые вы сделали,\nчтобы поклоняться им, и Я переселю вас дальше\nВавилона».","44":"Скиния свидетельства была у отцов наших в\nпустыне, как повелел Говоривший Моисею сделать её\nпо образу, который тот увидел.","45":"Её, получив по преемству, и внесли отцы наши с\nИисусом во владения народов, которых изгнал Бог от\nлица отцов наших. Так было до дней Давида,","46":"который обрел благодать пред Богом и молился о\nтом, чтобы найти жилище Богу Иакова.","47":"Соломон же воздвиг Ему дом.","48":"Но не живет Всевышний в рукотворенном, как\nговорит пророк:","49":"«Небо – Мне престол, а земля – подножие ног\nМоих. Какой дом вы построите Мне, говорит Господь,\nили какое место покоя Моего?","50":"Не Моя ли рука сотворила это всё?»","51":"Жестоковыйные и необрезанные сердцем и\nушами, вы всегда Духу Святому противитесь, как отцы\nваши, так и вы.","52":"Кого из пророков не гнали отцы ваши? И убили\nони\nпредвозвестивших\nпришествие\nПраведного,\nКоторого\nпредателями\nи\nубийцами\nвы\nтеперь\nсделались,","53":"вы, которые получили Закон в наставлениях\nангельских и не сохранили.","54":"Слыша это, они кипели бешенством в сердцах\nсвоих и скрежетали на него зубами.","55":"А он, полный Духа Святого, устремил взор к небу\nи увидел славу Божию и Иисуса, стоящего по правую\nсторону Бога,","56":"и сказал: вот я вижу отверстые небеса и Сына\nЧеловеческого стоящего по правую сторону Бога.","57":"Они же, закричав громким голосом, зажали уши\nсвои и устремились единодушно на него;","58":"и, выгнав его за пределы города, побивали\nкамнями. И свидетели сложили одежды свои у ног\nюноши, называемого Савлом.","59":"И побивали камнями Стефана, а он взывал и\nговорил: Господи Иисусе, прими дух мой.","60":"И склонив колени, воскликнул громким голосом:\nГосподи, не вмени им этого греха! И сказав это, почил."},"8":{"1":"Савл же одобрял убиение его. И разразилось в тот\nдень великое гонение на церковь Иерусалимскую, и все,\nкроме апостолов, рассеялись по разным местам Иудеи и\nСамарии.","2":"Стефана же похоронили благоговейные люди и\nсделали великий плач по нем.","3":"А Савл опустошал церковь, входя в дома, и, влача\nмужчин и женщин, отдавал в тюрьму.","4":"Между тем, рассеявшиеся пошли в разные\nстороны, благовествуя слово.","5":"А\nФилипп,\nпридя\nв\nгород\nСамарийский,\nпроповедовал им Христа.","6":"Толпы народа единодушно внимали тому, что\nговорил Филипп, слыша и видя знамения, которые он\nтворил.","7":"Ибо многие из одержимых духами нечистыми,\nкоторые\nвыходили\nс\nгромким\nвоплем,\nи\nмногие\nрасслабленные и хромые были исцелены.","8":"И была великая радость в том городе.","9":"Муж некий, по имени Симон, был уже раньше в\nгороде,\nзанимаясь\nволшебством\nи\nизумляя\nнарод\nСамарийский, выдавая себя за какого-то великого,","10":"Ему внимали все от мала до велика, говоря: это –\nсила Божия, называемая Великой.","11":"А внимали ему, потому что он долгое время\nизумлял их волшебством.","12":"Но когда поверили Филиппу, благовествующему\nо Царстве Божием и об имени Иисуса Христа, то были\nкрещены и мужчины и женщины.","13":"А Симон и сам уверовал и, приняв крещение, не\nотходил от Филиппа, и видя, что совершаются знамения\nи силы великие, изумлялся.","14":"Услышав же, что Самария приняла слово Божие,\nнаходившиеся в Иерусалиме апостолы послали к ним\nПетра и Иоанна,","15":"которые пришли и помолились о них, чтобы они\nприняли Духа Святого.","16":"Ибо Он еще не сходил ни на кого из них, а только\nбыли они крещены во имя Господа Иисуса.","17":"Тогда они возлагали руки на них, и те принимали\nДуха Святого.","18":"Симон же, увидев, что чрез возложение рук\nапостолов подается Дух Святой, принес им деньги,","19":"говоря: дайте и мне власть эту, чтобы тот, на\nкого я возложу руки, получал Духа Святого.","20":"Но Петр сказал ему: серебро твое с тобою да\nбудет в погибель, потому что ты помыслил дар Божий\nприобрести за деньги.","21":"Нет тебе в этом части, ни жребия. Ибо сердце\nтвое не право пред Богом.","22":"Итак покайся в этом зле твоем и помолись\nГосподу, может быть, будет отпущен тебе умысел\nсердца твоего:","23":"ибо вижу, что ты – в горькой желчи и в узах\nнеправды.","24":"Симон же сказал в ответ: помолитесь вы за меня\nГосподу, чтобы не постигло меня ничто из сказанного\nвами.","25":"Они же, засвидетельствовав и проповедав слово\nГосподне, пошли обратно в Иерусалим и во многих\nселениях Самарянских благовествовали.","26":"А ангел Господень сказал Филиппу: встань и к\nполудню иди на дорогу, спускающуюся от Иерусалима к\nГазе. Она безлюдна.","27":"И встав, он пошел. И вот муж Эфиоп, евнух,\nвельможа Кандакии, царицы Эфиопской, который был\nнад всей ее казной. Он ходил для поклонения в\nИерусалим,","28":"и возвращался. И сидел он на своей колеснице и\nчитал пророка Исаию.","29":"И Дух сказал Филиппу: подойди и пристань к\nэтой колеснице,","30":"И подбежав, Филипп услышал, что он читает\nИсаию пророка,","31":"и сказал: да понимаешь ли ты, что читаешь? А он\nсказал: как мне понять, если кто не наставит меня? И\nпопросил Филиппа подняться и сесть с ним.","32":"А место Писания, которое он читал, было такое:\nКак овца на заклание Он был приведен, и как агнец\nпред стригущим Его безгласен, так Он не отверзает уст\nСвоих.","33":"В\nунижении\nЕго,\nбыло\nотказано\nЕму\nв\nправосудии. Род Его кто изъяснит? Ибо жизнь Его\nизъемлется от земли.","34":"И обращаясь к Филиппу, евнух сказал: прошу\nтебя, о ком пророк говорит это: о себе или о ком-нибудь\nдругом?","35":"Филипп же отверз уста свои и, начав от этого\nписания, благовествовал ему Иисуса.","36":"Двигались они по дороге и пришли к какой-то\nводе. И говорит евнух: вот вода; что препятствует мне\nкреститься?","37":"И сказал ему Филипп: если веруешь от всего\nсердца, можно. Он же сказал в ответ: верую, что Иисус\nХристос есть Сын Божий.","38":"И приказал остановить колесницу, и сошли оба в\nводу, как Филипп, так и евнух, и он крестил его.","39":"Когда же они вышли из воды. Дух Господень\nвосхитил Филиппа, и больше не видел его евнух, и\nпродолжал он, радуясь, свой путь.","40":"А\nФилипп\nоказался\nв\nАзоте\nи,\nпроходя,\nблаговествовал всем городам, доколе не пришел в\nКесарию."},"9":{"1":"А Савл, всё еще дыша угрозой и убийством на\nучеников Господних, явился к первосвященнику","2":"и испросил у него письма в Дамаск к синагогам,\nчтобы кого найдет стоящих на этом Пути, и мужчин и\nженщин, привести в узах в Иерусалим,","3":"И было в дороге: приближался он к Дамаску, и\nвнезапно осиял его свет с неба.","4":"И, упав на землю, он услышал голос, говорящий\nему: Савл, Савл, что ты Меня гонишь?","5":"И он сказал: кто Ты, Господи? А Он: Я Иисус,\nКоторого ты гонишь.","6":"Но встань и войди в город, и будет тебе сказано,\nчто надлежит тебе делать.","7":"Люди\nже,\nсопутствующие\nему,\nстояли\nв\nоцепенении, слыша голос и никого не видя.","8":"Савл же встал с земли и с открытыми глазами\nничего не видел. И ведя его за руку, ввели в Дамаск.","9":"И три дня он не видел, и не ел, и не пил.","10":"Был некий ученик в Дамаске по имени Анания. И\nсказал ему в видении Господь: Анания! Он же сказал:\nвот я, Господи,","11":"И Господь к нему: встань и пойди на улицу,\nкоторая называется «Прямая», и в доме Иуды спроси\nТарсянина по имени Савла. Ибо вот он молится,","12":"и увидел в видении, что муж по имени Анания\nвошел и возложил на него руки, чтобы он прозрел.","13":"Но Анания ответил: я слышал от многих об этом\nчеловеке, сколько зла он сделал святым Твоим в\nИерусалиме.","14":"И здесь он имеет власть от первосвященников\nзаключить в узы всех призывающих имя Твое.","15":"Но Господь сказал ему: иди, потому что он у\nМеня сосуд избранный, чтобы пронести имя Мое и пред\nязычниками,\nи\nпред\nцарями,\nи\nпред\nсынами\nИзраилевыми.","16":"Ибо я покажу ему всё, что он должен претерпеть\nза имя Мое.","17":"И пошел Анания и вошел в тот дом, и, возложив\nна него руки, сказал: Савл брат, Господь послал меня,\nИисус, явившийся тебе на пути, которым ты шел, чтобы\nты прозрел и исполнился Духа Святого.","18":"И тотчас как бы чешуя отпала от его глаз, и он\nпрозрел, и встал и был крещен.","19":"И приняв пищу, укрепился. Пробыл он с\nучениками, что в Дамаске, несколько дней.","20":"И тотчас в синагогах начал проповедовать\nИисуса, что Он есть Сын Божий.","21":"И изумлялись все слышавшие и говорили: не тот\nли это, кто истребил в Иерусалиме призывающих Имя\nэто, и сюда не для того ли пришел, чтобы отвести их в\nузах к первосвященникам?","22":"Савл же всё более укреплялся и приводил в\nзамешательство\nИудеев,\nживущих\nв\nДамаске,\nдоказывая, что это Христос.","23":"Когда же прошло немало дней, сговорились\nИудеи убить его.","24":"Но заговор их стал известен Савлу. А они\nстерегли и ворота, как днем так и ночью, чтобы его\nубить.","25":"Но ученики его ночью взяли и спустили его по\nстене в корзине.","26":"Прибыв в Иерусалим, он пытался пристать к\nученикам. Но все боялись его, не веря, что он ученик.","27":"Варнава же, взяв его, привел к апостолам и\nрассказал им, как он в пути увидел Господа, и что\nГосподь говорил ему, и как он в Дамаске дерзновенно\nговорил во имя Иисуса.","28":"И был он о ними, входя и исходя в Иерусалиме,\nдерзновенно говоря во имя Господа.","29":"И с Еллинистами он говорил и спорил, и они\nпокушались убить его.","30":"Братья же, узнав, отвели его в Кесарию и\nотослали его в Тарс.","31":"Итак церковь по всей Иудее, Галилее и Самарии\nимела мир, назидаясь и ходя в страхе Господнем, и\nутешением Святого Духа умножалась.","32":"И было, что Петр, обходя всех, пришел и к\nсвятым, живущим в Лидде.","33":"И нашел он там одного человека по имени Энея,\nвосемь лет лежащего в постели; был он расслабленный.","34":"И сказал ему Петр: Эней, исцеляет тебя Иисус\nХристос. Встань и перестели себе постель. И он тотчас\nвстал.","35":"И видели его все живущие в Лидде и Сароне,\nкоторые и обратились к Господу.","36":"А в Иоппии была некая ученица по имени Тавифа,\nчто значит в переводе «серна». Она была богата\nдобрыми делами и милостынею, которую творила.","37":"И было в те дни: заболела она и умерла. Обмыв,\nеё положили в горнице.","38":"А так как Лидда была близко от Иоппии, то\nученики, услышав, что Петр там, послали к нему двух\nчеловек прося: не замедли придти к нам.","39":"Петр встал и пошел с ними. Когда он прибыл, его\nповели наверх в горницу, и все вдовы предстали перед\nним, плача и показывая ему все те рубашки и платья,\nкоторые делала Серна, пока была с ними.","40":"Но Петр, выслав всех вон и преклонив колени,\nпомолился и, обратившись к телу, сказал: Тавифа,\nвстань! И она открыла глаза свои и, увидев Петра, села.","41":"Он же, подав ей руку, поднял ее. И позвав святых\nи вдов, представил ее живой.","42":"И стало это известно по всей Иоппии, и\nуверовали многие в Господа.","43":"И было, что он немало дней пробыл в Иоппии у\nнекоего Симона Кожевника."},"10":{"1":"Муж же некий в Кесарии, по имени Корнилий,\nсотник из когорты, называемой Италийской,","2":"благочестивый и боящийся Бога со всем домом\nсвоим, творящий много милостыни народу и молящийся\nБогу постоянно,","3":"увидел ясно в видении, приблизительно около\nдевятого часа, ангела Божия, который вошел к нему и\nсказал ему: Корнилий!","4":"Он же, устремив на него взгляд и придя в страх,\nсказал: что, Господи? И он сказал ему: молитвы твои и\nмилостыни твои вознеслись, как жертва воспоминания,\nпред Богом.","5":"И теперь отправь людей в Иоппию и пошли за\nнеким Симоном, который прозывается Петром;","6":"он гостит у некоего Симона Кожевника, у которого\nдом близ моря.","7":"Когда ангел, говоривший ему, отошел, он позвал\nдвух\nиз\nдомочадцев\nи\nблагочестивого\nвоина,\nиз\nсостоявших при нем,","8":"и изложив им все, послал их в Иоппию.","9":"А на другой день, когда они были в пути и\nприближались к городу, взошел Петр на кровлю\nпомолиться около шестого часа.","10":"И почувствовал он голод и хотел есть. И пока\nготовили, нашло на него исступление,","11":"И видит он, что небо открыто, и сходит некий\nсосуд, вроде большой скатерти, за четыре конца\nспускаемый на землю;","12":"в нем были все четвероногие и пресмыкающиеся\nземные и птицы небесные.","13":"И был голос к нему: встань, Петр, заколи и ешь.","14":"Но Петр сказал: никоим образом, Господи,\nпотому что я никогда не ел ничего скверного или\nнечистого.","15":"И голос снова во второй раз к нему: что Бог\nочистил, ты не объявляй нечистым.","16":"Это было трижды, и тотчас вознесён был сосуд\nна небо.","17":"Когда же Петр недоумевал про себя, что бы\nзначило видение, которое он видел, – вот люди,\nпосланные Корнилием, расспросив о доме Симона,\nподошли к воротам.","18":"и, возвысив голос, начали спрашивать, здесь ли\nгостит Симон, прозываемый Петром.","19":"И пока Петр размышлял о видении, сказал ему\nДух: вот три человека ищут тебя.","20":"Но встань, спустись и иди к ним без всякого\nсомнения, потому что Я послал их.","21":"И сойдя к людям, Петр сказал: вот я, кого вы\nищете. По какому делу вы пришли?","22":"Они\nже\nсказали:\nКорнилий\nсотник,\nмуж\nправедный\nи\nбоящийся\nБога,\nимеющий\nдоброе\nсвидетельство от всего народа Иудейского, получил\nуказание от святого ангела вызвать тебя в дом свой и\nпослушать твоих речей.","23":"Пригласив их, он оказал им гостеприимство. А на\nдругой день он встал и вышел с ними, и некоторые из\nбратьев Иоппийских пошли с ним.","24":"А на следующий день вошли они в Кесарию.\nКорнилий же ожидал их, созвав родственников своих и\nближайших друзей.","25":"А когда Петр готов был войти, Корнилий,\nвстретив его, пал к его ногам и поклонился.","26":"Но Петр поднял его говоря: встань, сам я тоже\nчеловек.","27":"И беседуя с ним, вошел, и находит многих в\nсборе,","28":"и сказал он им: вы знаете, как незаконно для\nИудея сближаться с иноплеменником или приходить к\nнему; а мне Бог указал не называть ни одного человека\nскверным или нечистым.","29":"Поэтому я и пришел беспрекословно, будучи\nпозван. Итак, я спрашиваю: по какой причине вы\nпослали за мной?","30":"И Корнилий сказал: в этот час пошел четвертый\nдень, как я, в девятый час, молился у себя в доме, и вот\nстал передо мною муж в одежде блестящей","31":"и говорит: Корнилий, услышана твоя молитва, и\nмилостыни твои воспомянуты пред Богом.","32":"Итак, пошли в Иоппию за Симоном, который\nпрозывается\nПетром:\nон\nгостит\nв\nдоме\nСимона\nКожевника близ моря».","33":"Поэтому я тотчас же послал к тебе, и ты хорошо\nсделал, что пришел. Теперь же мы все пред Богом,\nчтобы выслушать всё, что повелено тебе Господом.","34":"Петр\nотверз\nуста\nи\nсказал:\nПоистине\nя\nубеждаюсь, что Бог нелицеприятен,","35":"но во всяком народе боящийся Его и делающий\nправду приятен Ему.","36":"Он\nпослал\nсынам\nИзраилевым\nслово,\nблаговествуя мир чрез Иисуса Христа: Этот есть\nГосподь всех.","37":"Вы знаете, что произошло по всей Иудее,\nначиная\nот\nГалилеи,\nпосле\nкрещения,\nкоторое\nпроповедал Иоанн:","38":"об Иисусе из Назарета, как помазал Его Бог\nДухом Святым и силою, и Он ходил, благотворя и\nисцеляя всех угнетаемых диаволом, потому что Бог был\nс Ним.","39":"И мы свидетели всего, что сделал Он в стране\nИудейской и в Иерусалиме. Его они и убили, повесив на\nдреве.","40":"Его Бог воздвиг в третий день и дал Ему являться","41":"–\nне\nвсему\nнароду,\nно\nсвидетелям,\nпредызбранным Богом, нам, которые с Ним ели и пили\nпо воскресении Его из мертвых.","42":"И Он повелел нам проповедать народу и\nзасвидетельствовать, что Он есть поставленный Богом\nСудия живых и мертвых.","43":"О Нем все пророки свидетельствуют, что всякий\nверующий в Него получит отпущение грехов именем\nЕго.","44":"Петр еще произносил эти слова, как сошел Дух\nСвятой на всех слышащих слово.","45":"И изумились верующие из обрезанных, которые\nпришли с Петром, что дар Святого Духа излился и на\nязычников;","46":"ибо они слышали их, говорящих языками и\nвеличающих Бога.","47":"Тогда ответил Петр: может ли кто отказать в\nводе крещения тем, кто приняли Духа Святого, как и\nмы?","48":"И велел им креститься во имя Иисуса Христа.\nТогда они попросили его остаться на несколько дней."},"11":{"1":"Между тем услышали апостолы и братья, бывшие\nв Иудее, что и язычники приняли слово Божие.","2":"И когда Петр пришел в Иерусалим, начали спорить\nс ним обрезанные,","3":"говоря: ты вошел к людям необрезанным и ел с\nними.","4":"И Петр начал рассказывать им по порядку, говоря:","5":"в городе Иоппии я молился и видел в исступлении\nвидение: сходит некий сосуд, вроде большой скатерти,\nза четыре конца спускаемой с неба, и он дошел до меня.","6":"Я устремил взор и всматривался в него и увидел\nчетвероногих земных и зверей и пресмыкающихся и\nптиц небесных.","7":"Услышал я и голос, говорящий мне: «встань, Петр,\nзаколи и ешь».","8":"Но я сказал: «никоим образом, Господи, потому\nчто скверное или нечистое никогда не входило в уста\nмои».","9":"И ответил во второй раз голос с неба: «что Бог\nочистил, ты не объявляй нечистым».","10":"Это было трижды, и снова было поднято всё на\nнебо.","11":"И вот, тотчас три человека подошли к дому, в\nкотором я был, посланные из Кесарии ко мне.","12":"И сказал мне Дух пойти с ними, ничуть не\nсомневаясь. Пошли со мной и эти шесть братьев, и\nвошли мы в дом того человека.","13":"И он рассказал нам, как он увидел у себя в доме\nангела, который стал и сказал: «пошли в Иоппию и\nвызови Симона, прозываемого Петром:","14":"он скажет тебе слова, которыми будешь спасен\nты и весь дом твой».","15":"Когда же начал я говорить, сошел на них Дух\nСвятой, как и на нас в начале.","16":"И вспомнил я слово Господа, как Он говорил:\n«Иоанн крестил водою, вы же будете крещены Духом\nСвятым».","17":"Итак, если такой же дар дал им Бог, как и нам,\nуверовавшим в Господа Иисуса Христа, кто был я, чтобы\nмог воспрепятствовать Богу?","18":"Услышав это, они успокоились и прославили\nБога, говоря: видно, и язычникам дал Бог покаяние в\nжизнь.","19":"Между\nтем,\nрассеявшиеся\nот\nгонения,\nпроисшедшего из-за Стефана, прошли до Финикии, и\nКипра, и Антиохии, никому не проповедуя слова, кроме\nодних только Иудеев.","20":"Были же некоторые из них Кипряне и Киринеяне,\nкоторые, придя в Антиохию, говорили и Еллинам,\nблаговествуя Господа Иисуса.","21":"И была рука Господня с ними, и большое число,\nуверовав, обратилось к Господу.","22":"И дошел слух о них до церкви в Иерусалиме, и\nпослали Варнаву в Антиохию.","23":"Он,\nприбыв\nи\nувидев\nблагодать\nБожию,\nвозрадовался\nи\nувещал\nвсех\nдержаться\nГоспода\nискренним сердцем,","24":"потому что был он муж добрый и полный Духа\nСвятого и веры. И множество их присоединилось к\nГосподу.","25":"А он пошел в Тарс в поисках Савла","26":"и, найдя, привел в Антиохию. И было так, что в\nтечение целого года они собирались с церковью и учили\nмножество народа, и впервые в Антиохии ученики\nполучили имя христиан.","27":"И в эти дни пришли из Иерусалима в Антиохию\nпророки.","28":"И встав, один из них по имени Агав предсказывал\nДухом, что голод великий будет по всей вселенной,\nкаковой и наступил при Клавдии.","29":"И они определили, чтобы каждый из учеников, по\nсвоему достатку, послал пособие братьям, живущим в\nИудее,","30":"что они и сделали, послав пресвитерам через\nВарнаву и Савла."},"12":{"1":"А в то время царь Ирод наложил руки на\nнекоторых, принадлежащих к церкви, чтобы сделать им\nзло.","2":"Он убил Иакова, брата Иоаннова, мечом,","3":"Увидев же, что это приятно Иудеям, решил\nзадержать кроме того и Петра: а были дни Опресноков.","4":"Он и взял его, посадил в тюрьму и поручил\nчетырем четверицам воинов стеречь его, намереваясь\nпосле Пасхи вывести его к народу.","5":"Итак, Петра стерегли в тюрьме, а церковь усердно\nмолилась о нем Богу.","6":"Когда же Ирод собирался вывести его, – в ту ночь\nПетр спал между двумя воинами, связанный двумя\nцепями, и стражи у двери стерегли тюрьму.","7":"И вот предстал ангел Господень, и свет воссиял в\nтемнице. Толкнув Петра в бок, он разбудил его, говоря:\nвстань скорее. И спали цепи его с рук.","8":"И сказал ему ангел: опояшься и надень твои\nсандалии. И он сделал так. И говорит он ему: оденься в\nодежду твою и следуй за мной.","9":"И выйдя, он следовал за ним, и не знал, что\nтворимое ангелом есть действительность, но думал, что\nвидит видение,","10":"Пройдя же первую стражу и вторую, они пришли\nк железным воротам, ведущим в город, которые сами\nсобой отворились им, и выйдя, они прошли одну улицу,\nи тотчас отделился от него ангел,","11":"И Петр, придя в себя, сказал: теперь я вижу\nвоистину, что послал Господь ангела Своего и избавил\nменя от руки Ирода и от всего, чего ждал народ\nИудейский.","12":"И осмотревшись, он пришел к дому Марии,\nматери Иоанна, прозываемого Марком, где многие\nсобрались и молились.","13":"И когда он постучался в дверь в воротах,\nподошла послушать служанка, по имени Рода,","14":"и, узнав голос Петра, от радости не отворила\nворот, но вбежав, объявила, что Петр стоит у ворот.","15":"А они ей сказали: ты не в своем уме. Но она\nутверждала, что это так. А они говорили: это ангел его.","16":"Между тем Петр продолжал стучаться. И\nотворив, увидели его и изумились.","17":"Он же, дав им знак рукой, чтобы молчали,\nрассказал им, как Господь его вывел из тюрьмы, и\nсказал: объявите об этом Иакову и братьям. И выйдя,\nнаправился в другое место.","18":"А когда настал день, было немалое волнение\nсреди воинов: что же случилось с Петром?","19":"Ирод же, поискав его и не найдя, подверг\nстражей допросу и повелел казнить. И отправившись из\nИудеи в Кесарию, оставался там.","20":"Он был крайне раздражен на Тирян и Сидонян;\nони же, с общего согласия, явились к нему и, склонив на\nсвою сторону Власта, постельничего царского, просили\nмира, так как область их питалась от области царской.","21":"В назначенный же день Ирод, одевшись в\nцарскую одежду, сел на возвышенном месте и держал к\nним речь.","22":"А народ восклицал: голос бога, а не человека!","23":"И тотчас поразил его ангел Господень за то, что\nне воздал он славы Богу, и, изъеденный червями, он\nиспустил дух.","24":"А слово Божие росло и распространялось.","25":"Варнава\nже\nи\nСавл,\nисполнив\nслужение,\nвозвратились из Иерусалима, захватив с собой и\nИоанна, прозванного Марком."},"13":{"1":"Были же в Антиохии в местной церкви пророки и\nучители: Варнава, Симеон, называемый Нигер, и Лукий\nКиринеянин, Манаин, приближенный Ирода тетрарха, и\nСавл.","2":"Когда они служили Господу и постились, Дух\nСвятой сказал: отделите Мне Варнаву и Савла на дело, к\nкоторому Я призвал их.","3":"Тогда они, совершив пост и молитву и возложив на\nних руки, отпустили их.","4":"Итак, посланные Святым Духом, они пришли в\nСелевкию, а оттуда отплыли в Кипр,","5":"и прибыв в Саламин, проповедовали слово Божие\nв синагогах Иудейских; был же с ними и Иоанн, как\nпомощник.","6":"Пройдя весь остров до Пафа, они нашли некоего\nчеловека волхва, Иудейского лжепророка, которому имя\nВариисус.","7":"Он был с проконсулом Сергием Павлом, мужем\nразумным. Этот, призвав Варнаву и Савла, пожелал\nуслышать слово Божие.","8":"Но противодействовал им Элима волхв (ибо таково\nв переводе имя его), стараясь отвратить проконсула от\nверы.","9":"Но исполнившись Духа Святого, Савл, он же и\nПавел, устремив на него взор,","10":"сказал: о полный всякого коварства и всякого\nзла, сын диавола, враг всякой правды, перестанешь ли\nты искривлять прямые пути Господни?","11":"И теперь, вот рука Господня на тебе, и ты\nбудешь слеп, не видя солнца до времени. И тотчас\nнапала на него мгла и тьма, и обращаясь во все\nстороны, он искал поводыря.","12":"Тогда\nпроконсул,\nувидев\nпроисшедшее,\nуверовал, дивясь учению Господню.","13":"А Павел и бывшие с ним, отплыв из Пафа,\nприбыли в Пергию в Памфилии. Иоанн же, отделившись\nот них, вернулся в Иерусалим.","14":"Они же, пройдя путь от Пергии, прибыли в\nАнтиохию Писидийскую и, придя в синагогу в день\nсубботний, сели.","15":"И после чтения Закона и Пророков начальники\nсинагоги послали им сказать: мужи братья, если у вас\nесть слово наставления к народу, говорите.","16":"И Павел, встав и дав знак рукой, сказал: мужи\nИзраильские и боящиеся Бога, послушайте.","17":"Бог народа этого, Израиля, избрал отцов наших и\nвозвысил\nнарод\nво\nвремя\nпребывания\nв\nземле\nЕгипетской, и рукою высокою вывел их из нее,","18":"и около сорока лет терпел их в пустыне","19":"и, истребив семь народов в земле Ханаанской,\nдал им в наследие землю их","20":"приблизительно на четыреста пятьдесят лет. И\nпосле этого дал судей до Самуила пророка.","21":"И затем они просили царя, и дал им Бог Саула,\nсына Киса, мужа из колена Вениаминова, на сорок лет.","22":"И отстранив его, Он воздвиг им в цари Давида, о\nкотором и сказал во свидетельство: «Я нашел Давида,\nсына Иессея., мужа по сердцу Моему, который исполнит\nвсю волю Мою».","23":"От его-то семени Бог, по обещанию, привел\nИзраилю Спасителя Иисуса","24":"после того, как Иоанн проповедовал, перед\nсамым явлением Его, крещение покаяния всему народу\nИзраильскому.","25":"А когда Иоанн завершил свое поприще, он\nговорил: «я не то, что вы обо мне думаете; но вот, идет\nза мною Тот, у Которого я недостоин развязать обувь на\nногах».","26":"Мужи братья, сыны рода Авраамова, и боящиеся\nБога между вами: нам послано слово спасения этого.","27":"Ибо живущие в Иерусалиме и начальники их, не\nузнав Его, исполнили и голоса пророков, читаемые\nкаждую субботу, осудив Его.","28":"И не найдя никакого основания для смерти,\nупросили Пилата убить Его.","29":"Когда же исполнили всё написанное о Нем, то,\nсняв с древа, положили Его в гробницу,","30":"Но Бог воздвиг Его из мертвых.","31":"Он являлся в течение многих дней пришедшим\nвместе с Ним из Галилеи в Иерусалим. Они теперь\nсвидетели Его перед народом.","32":"И мы вам благовествуем обещание, которое дано\nбыло отцам,","33":"что Бог его исполнил для нас, их детей,\nвоскресив Иисуса, как и написано в псалме втором: «Ты\n– Сын Мой, Я сегодня родил Тебя».","34":"А что Он воскресил Его из мертвых, так что Он\nуже не обратится в тление, – Он сказал так: «Я дам вам\nсвятое достояние Давидово непреложное».","35":"Поэтому Он и в другом месте говорит: «Ты не\nдашь святому Твоему увидеть тление».","36":"Но Давид, послужив в своем поколении совету\nБожию, почил и приложился к отцам своим и увидел\nтление.","37":"Тот же, Кого Бог воздвиг, не увидел тления.","38":"Итак, да будет известно вам, мужи братья, что\nради Него вам возвещается отпущение грехов, и во\nвсём, в чем вы не могли быть оправданы Законом\nМоисеевым,","39":"всякий верующий оправдывается Им.","40":"Итак, берегитесь, чтобы не пришло на вас\nсказанное у Пророков:","41":"«Посмотрите, презрители, подивитесь и сгиньте,\nпотому что дело делаю Я в дни ваши, дело, которому вы\nникак не поверите, если кто расскажет вам».","42":"И когда они выходили, их просили, чтобы в\nследующую субботу им сказаны были эти слова.","43":"И когда собрание было распущено, последовали\nмногие из Иудеев и благоговейных прозелитов за\nПавлом и Варнавой, которые, беседуя с ними, убеждали\nих пребывать в благодати Божией.","44":"А в следующую субботу почти весь город\nсобрался слушать слово Божие.","45":"Но Иудеи, увидев толпу народа, исполнились\nзависти и возражали с хулой тому, что говорил Павел.","46":"А Павел и Варнава с дерзновением сказали: вам\nпрежде всего должно было быть проповедано слово\nБожие. Так как вы отвергаете его и не считаете себя\nдостойными вечной жизни, то вот, мы обращаемся к\nязычникам.","47":"Ибо так заповедал нам Господь: «Я положил Тебя\nво свет язычникам, чтобы Ты был во спасение до края\nземли».","48":"Слыша это, язычники радовались и прославляли\nслово\nГосподне,\nи\nуверовали\nвсе,\nкоторые\nбыли\nпредназначены к жизни вечной.","49":"И распространялось слово Господне по всей\nстране.","50":"Но Иудеи настроили благоговейных почтенных\nженщин и первых людей города и подняли гонение на\nПавла и Варнаву и изгнали их из своих пределов.","51":"А они, стряхнув на них пыль со своих ног, пришли\nв Иконию.","52":"Ученики же исполнялись радости и Святого Духа."},"14":{"1":"И было, что в Иконии они таким же образом вошли\nв Иудейскую синагогу и говорили, так что уверовало\nвеликое множество, как Иудеев, так и Еллинов.","2":"Но Иудеи, оставшиеся непокорными, возбудили и\nозлобили души язычников против братьев.","3":"Пробыли же они немалое время, говоря с\nдерзновением в Господе, Который свидетельствовал о\nслове благодати Своей и давал совершаться руками их\nзнамениям и чудесам.","4":"Население города раскололось, и одни были с\nИудеями, другие – с апостолами.","5":"Когда же у язычников и Иудеев с начальниками их\nвозникло стремление подвергнуть их насилию и побить\nкамнями,","6":"они, узнав, бежали в Ликаонские города Листру и\nДервию и окрестную область,","7":"и там благовествовали.","8":"И некий муж в Листрах, не владевший ногами,\nсидел; хромой от чрева матери своей, он никогда не\nходил.","9":"Он слышал, как говорил Павел, который, устремив\nна него взор и увидев, что он имеет веру, чтобы быть\nспасенным,","10":"сказал громким голосом: встань на ноги твои\nпрямо. И он вскочил и стал ходить.","11":"Народ же, увидев, что сделал Павел, возвысил\nсвой\nголос,\nговоря\nпо-ликаонски:\nбоги\nв\nобразе\nчеловеческом сошли к нам.","12":"И называли они Варнаву Зевсом, а Павла\nГермесом, так как он держал речь.","13":"И жрец Зевса, стоящего перед городом, доставив\nк воротам быков и венки, хотел с народом принести\nжертву.","14":"Но\nапостолы\nВарнава\nи\nПавел,\nуслышав,\nразорвали одежды свои и с криком бросились в толпу,","15":"говоря: мужи, что это вы делаете? И мы –\nподобные вам люди, благовествующие вам, чтобы вы от\nэтих суетных богов обратились к Богу живому, Который\nсотворил небо и землю, и море и всё, что в них,","16":"Который в прошедших поколениях позволил всем\nнародам ходить своими путями,","17":"хотя и не переставал свидетельствовать о Себе,\nтворя добро, подавая вам с неба дожди и времена\nплодоносные, исполняя пищею и радостью сердца\nваши.","18":"И говоря это, они едва успокоили народ, чтобы\nне приносили им жертвы.","19":"Но пришли из Антиохии и Иконии Иудеи и,\nнастроив народ, побили Павла камнями и вытащили за\nгород, думая, что он мертв.","20":"Но после того, как ученики обступили его кругом,\nон встал и вошел в город. И на другой день он вышел с\nВарнавой в Дервию.","21":"И благовествовав этому городу и приобретя\nдостаточно учеников, они возвратились в Листру и в\nИконию и в Антиохию,","22":"утверждая души учеников, увещая пребывать в\nвере и поучая, что многими скорбями надлежит нам\nвойти в Царство Божие.","23":"И поставив им в каждой церкви пресвитеров,\nони, помолившись с постом, предали их Господу, в\nКоторого уверовали.","24":"И пройдя через Писидию, они пришли в\nПамфилию","25":"и, проповедав слово Господне в Пергии, сошли в\nАтталию,","26":"и оттуда отплыли в Антиохию, откуда они были\nпреданы благодати Божией на дело, которое они\nисполнили.","27":"Прибыв же и собрав церковь, они возвестили всё,\nчто сотворил Бог с ними, и как Он открыл язычникам\nдверь веры.","28":"И оставались они немалое время с учениками."},"15":{"1":"И какие-то люди, пришедшие из Иудеи, учили\nбратьев: если вы не обрежетесь по обычаю Моисея, вы\nне можете спастись.","2":"Когда же у Павла и Варнавы возникло разногласие\nи немалый спор, было постановлено, чтобы Павел и\nВарнава и некоторые другие из них шли по этому\nвопросу к апостолам и пресвитерам в Иерусалим,","3":"Итак, церковь их отправила, и они проходили\nФиникию\nи\nСамарию,\nрассказывая\nоб\nобращении\nязычников, и вызывали радость великую у всех братьев.","4":"И прибыв в Иерусалим, они были приняты\nцерковью и апостолами и пресвитерами, и возвестили\nвсё, что Бог сотворил с ними.","5":"Но встали некоторые из толка фарисейского,\nуверовавшие, и говорили, что надо обрезывать их и\nтребовать соблюдать Закон Моисеев.","6":"И собрались апостолы и пресвитеры рассмотреть\nэто дело.","7":"После многих прений встал Петр и сказал им:\nмужи братья, вы знаете, что от дней начальных Бог в\nвашей среде сделал выбор, чтобы из моих уст услышали\nязычники слово Евангелия и уверовали.","8":"И Сердцеведец Бог дал им свидетельство, даровав\nДуха Святого, как и нам,","9":"и никакого различия не положил между нами и\nими, верою очистив сердца их.","10":"Так почему же вы теперь искушаете Бога,\nвозлагая на шею учеников ярмо, которого ни отцы\nнаши, ни мы не могли понести?","11":"Но по благодати Господа Иисуса верим, что мы\nспасены таким же образом, как и они.","12":"И всё собрание умолкло и слушали Варнаву и\nПавла, рассказывавших о всех тех знамениях и чудесах,\nкакие Бог сотворил через них среди язычников.","13":"После же того, как они умолкли, стал говорить\nИаков: мужи братья, выслушайте меня.","14":"Симеон изъяснил, как первоначально усмотрел\nБог взять из язычников народ, посвященный имени Его.","15":"И с этим согласны слова Пророков, как написано:","16":"«После этого Я возвращусь и воссоздам скинию\nДавидову падшую, и разрушенное в ней воссоздам, и\nисправлю её,","17":"дабы взыскали Господа остальные из людей и\nвсе язычники, над которыми наречено имя Мое над\nними», говорит Господь, делающий это","18":"известным от века.","19":"Я поэтому полагаю не затруднять обращающихся\nк Богу из язычников,","20":"но написать им, чтобы воздерживались от\nосквернения идолами, и от блуда, и от удавленины и от\nкрови [и чтобы не делали другим, чего не хотят себе].","21":"Ибо, читаемый в синагогах каждую субботу,\nМоисей от древних поколений имеет во всех городах\nпроповедующих его.","22":"Тогда угодно было апостолам и пресвитерам со\nвсею церковью, избрав из своей среды мужей, послать в\nАнтиохию с Павлом и Варнавой: Иуду, называемого\nВарсавой, и Силу, мужей, руководящих среди братьев,","23":"написав через них: апостолы и пресвитеры –\nбратья, – находящимся в Антиохии и Сирии и Киликии\nбратьям из язычников, радоваться.","24":"Так как мы услышали, что некоторые из нас\nсмутили вас своими словами, волнуя ваши души, – люди,\nкоторым мы не давали поручения,","25":"– угодно было нам с общего согласия, избрав\nмужей, послать к вам с возлюбленными нашими\nВарнавой и Павлом,","26":"людьми, предавшими души свои за имя Господа\nнашего Иисуса Христа.","27":"Итак, мы послали Иуду и Силу, которые объявят\nвам то же самое на словах.","28":"Ибо угодно было Духу Святому и нам не\nвозлагать на вас никакого лишнего бремени, кроме\nэтого необходимого:","29":"воздерживаться от идоложертвенного, и крови, и\nудавленины, и блуда. [И не делайте другому, чего не\nхотите себе]. Храня себя от этого, вы поступите хорошо.\nБудьте здоровы.","30":"Итак, простившись, они сошли в Антиохию, и,\nсобрав общину, вручили письмо.","31":"Те же, прочитав письмо, были рады этому\nнаставлению.","32":"А Иуда и Сила, будучи и сами пророками,\nобильным словом наставили братьев и утвердили,","33":"И проведя так некоторое время, они с миром\nотпущены были братьями к пославшим их.","34":"Но Силе угодно было остаться там,","35":"Павел же и Варнава оставались в Антиохии, уча и\nблаговествуя, совместно и с многими другими, слово\nГосподне.","36":"Но через несколько дней сказал Варнаве Павел:\nвернемся, посетим братьев в каждом городе, где мы\nвозвестили слово Господне: как они живут?","37":"Варнава же хотел взять с собой и Иоанна,\nназываемого Марком.","38":"Но Павел настаивал на том, чтобы того, кто\nотстал от них в Памфилии и не пошел с ними на дело,\nэтого с собой не брать.","39":"Произошло же острое разногласие, так что они\nрасстались друг с другом, и Варнава, взяв Марка,\nотплыл в Кипр,","40":"а Павла братья поручили благодати Господней, и\nон, избрав себе Силу, отправился в путь.","41":"И проходил Сирию и Киликию, утверждая\nцерковь."},"16":{"1":"Дошел он и до Дервии и до Листры. И вот некий\nученик был там по имени Тимофей, сын верующей\nИудеянки, но отца Еллина.","2":"О нем свидетельствовали братья в Листрах и\nИконии.","3":"Павел пожелал, чтобы он отправился в путь\nвместе с ним, и, взяв, обрезал его, ради Иудеев,\nнаходившихся в тех местах; ибо все знали, что отец его\nбыл Еллин.","4":"Когда\nже\nони\nпроходили\nпо\nгородам,\nто\nзаповедовали\nим\nсоблюдать\nпостановления,\nвынесенные апостолами и пресвитерами, собравшимися\nв Иерусалиме.","5":"И церкви утверждались в вере и численно\nвозрастали с каждым днем.","6":"Недопущенные Святым Духом проповедать слово\nв Асии, они прошли Фригию и Галатийскую страну.","7":"Дойдя до Мисии, они пытались отправиться в\nВифинию, но не позволил им Дух Иисуса.","8":"Миновав Мисию, они сошли в Троаду.","9":"И было ночью видение Павлу: некий муж\nМакедонянин стоял и просил его и говорил: перейди в\nМакедонию и помоги нам.","10":"И после того, как он это видение видел, тотчас\nпостарались мы переправиться в Македонию, заключая,\nчто призвал нас Бог благовествовать им.","11":"Итак, отплыв из Троады, мы пришли прямым\nпутем в Самофракию, а на другой день в Неаполис,","12":"и оттуда в Филиппы, город первой части\nМакедонии, колонию. Оставались мы в этом городе\nнесколько дней.","13":"А в день субботний вышли мы за ворота к реке,\nгде, как мы думали, было место для молитвы, и сев,\nразговаривали с собравшимися женщинами.","14":"И некая женщина слушала, по имени Лидия,\nторговавшая пурпуром, из города Фиатир, чтущая Бога:\nГосподь открыл её сердце внимать тому, что говорил\nПавел.","15":"И после того, как она была крещена и дом её, она\nпопросила нас, говоря: если вы сочли, что я верна\nГосподу, войдите в мой дом и живите. И она склонила\nнас.","16":"И было, когда мы шли на место молитвы,\nвстретилась\nнам\nнекая\nслужанка,\nимевшая\nдуха\nпрорицателя, которая, прорицая, доставляла своим\nгосподам большой заработок.","17":"Она, следуя за Павлом и за нами, кричала: эти\nлюди – рабы Бога Всевышнего, которые возвещают вам\nпуть спасения.","18":"И это она делала много дней. Но Павел, досадуя,\nповернулся и сказал духу: повелеваю тебе именем\nИисуса Христа выйти из неё. И он вышел в тот же час.","19":"Увидев же господа её, что ушла надежда их\nзаработка, схватили Павла и Силу и потащили на\nплощадь к начальникам,","20":"и приведя их к преторам сказали: эти люди,\nбудучи Иудеями, возмущают наш город","21":"и вводят обычаи, которых нам, Римлянам, не\nследует ни принимать, ни исполнять.","22":"И толпа также восстала на них, и преторы,\nсорвав с них одежды, велели бить их палками,","23":"и нанеся им много ударов, бросили в тюрьму,\nприказав тюремщику крепко стеречь их.","24":"Он,\nполучив\nтакой\nприказ,\nбросил\nих\nво\nвнутреннюю тюрьму и ноги их забил в колодки.","25":"Около полуночи Павел и Сила, молясь, воспевали\nБога, и слушали их узники.","26":"Но вдруг сделалось великое землетрясение, так\nчто поколебались основания тюрьмы. Тотчас отворились\nвсе двери, и со всех спали оковы.","27":"А тюремщик, проснувшись и увидев, что двери\nтюрьмы отворены, выхватил меч и хотел себя убить,\nдумая, что узники бежали.","28":"Но Павел крикнул громким голосом: не делай\nсебе никакого зла; мы, ведь, все здесь.","29":"Потребовав огня, он вбежал и в трепете пал\nперед Павлом и Силой на землю,","30":"и, выведя их вон, сказал: господа мои, что мне\nделать, чтобы спастись?","31":"Они же сказали: уверуй в Господа Иисуса и\nбудешь спасен ты и дом твой.","32":"И проповедали ему слово Господне и всем, кто в\nдоме его.","33":"И взяв их в тот же час ночи, он омыл им раны от\nпобоев, и тотчас был крещен сам и все домашние его,","34":"и приведя их в дом, предложил трапезу и\nвозрадовался всем домом тому, что уверовал в Бога.","35":"С наступлением же дня, послали преторы\nгородских служителей, говоря: отпусти тех людей.","36":"И объявил тюремщик слова эти Павлу: преторы\nприслали отпустить вас. Итак, выйдите теперь и идите\nс миром.","37":"Но Павел сказал им: нас, Римских граждан, без\nсуда всенародно били и бросили в тюрьму; и теперь\nтайно нас выгоняют? Так нет! Пусть придут и сами нас\nвыведут.","38":"Городские служители доложили преторам эти\nслова. И те испугались, услышав, что это – Римские\nграждане,","39":"и придя, успокоили их и выведя просили уйти из\nгорода.","40":"Они же, выйдя из тюрьмы, пришли к Лидии и\nувидев братьев, наставили их и отправились в путь."},"17":{"1":"Пройдя через Амфиполь и Апполонию, они пришли\nв Фессалонику, где была Иудейская синагога.","2":"Павел, по своему обыкновению, вошел к ним и три\nсубботы поучал их от Писаний,","3":"объясняя и доказывая, что Христу надлежало\nпострадать и воскреснуть из мертвых, и что это –\nХристос, Тот Иисус, Которого я возвещаю вам.","4":"И некоторые из них убедились и присоединились к\nПавлу и Силе, как из благоговейных Еллинов великое\nмножество, так и из знатных женщин немало.","5":"Но Иудеи, возревновав и подобрав из уличной\nчерни кое-каких негодных людей, собрались толпой и\nначали возмущать город. И подступив к дому Иасона,\nдомогались вывести их к народу.","6":"Но не найдя их, повлекли Иасона и некоторых\nбратьев к политархам, крича: эти люди, возмутившие\nвселенную, вот они и здесь!","7":"И принял их Иасон! И все они поступают против\nповелений Кесаря, называя царем другого, Иисуса.","8":"И толпа и политархи были смущены, слыша это,","9":"и взяв залог от Иасона и прочих, они отпустили их.","10":"Братья же немедленно ночью отправили Павла и\nСилу в Верию. Они, по прибытии, пошли в синагогу\nИудейскую.","11":"Эти были благороднее Фессалоникийских: они\nприняли слово со всяческим усердием, ежедневно\nисследуя Писания, так ли это.","12":"И многие из них уверовали: и из почтенных\nЕллинских женщин и из мужчин немало.","13":"Но когда Фессалоникийские Иудеи узнали, что и\nв Верии возвещено Павлом слово Божие, они пришли и\nтуда, волнуя и возмущая народ.","14":"Тогда братья тотчас отправили Павла к морю;\nСила же и Тимофей остались там.","15":"А провожавшие Павла довели его до Афин и,\nполучив приказание к Силе и Тимофею как можно\nскорее придти к нему, отправились в путь.","16":"И пока Павел ожидал их в Афинах, дух его в нем\nвозмущался, видя, что город полон идолов.","17":"Итак, он рассуждал в синагоге с Иудеями и\nчтущими\nБога,\nи\nна\nплощади\nкаждый\nдень\nсо\nслучайными встречными.","18":"А кое-кто и из эпикурейских и стоических\nфилософов встречался с ним, и некоторые говорили: что\nхочет сказать этот пустослов? А другие: кажется, это\nпроповедник\nчужих\nбогов,\n(потому\nчто\nон\nблаговествовал Иисуса и воскресение).","19":"И взяв его, привели в Ареопаг и говорили: можем\nли мы узнать, что это за новое учение, проповедуемое\nтобой?","20":"Ибо странное что-то вкладываешь ты в наши\nуши. Вот мы и хотим узнать, что это может быть?","21":"Афиняне же все и живущие у них чужестранцы\nничем другим не заполняли свои досуги, как тем, чтобы\nговорить или слушать что-нибудь новое.","22":"И Павел, став посредине Ареопага, сказал: мужи\nАфиняне,\nпо\nвсему\nвижу,\nчто\nвы\nособенно\nбогобоязненны.","23":"Ибо, проходя и осматривая ваши святыни, я\nнашел и жертвенник, на котором было написано:\n«неведомому богу». Итак, что вы, не зная, чтите, я\nвозвещаю это вам.","24":"Бог, сотворивший мир и всё, что в нём, Он,\nГосподь неба и земли, не в рукотворенных храмах\nобитает,","25":"и не руками человеческими воздается Ему\nслужение, как имеющему в чем-либо нужду: Он Сам\nдарует всем жизнь и дыхание и всё.","26":"И произвёл Он от одного весь род человеческий:\nобитать по всему лицу земли, предуставив сроки и\nпределы их обитанию;","27":"искать Бога, не коснутся ли они Его и не найдут\nли, хотя и не далеко Он от каждого из нас.","28":"Ибо в Нем мы живем и движемся и существуем,\nкак и некоторые из ваших поэтов сказали: «Ведь мы Его\nи род».","29":"Итак, будучи родом Божиим, мы не должны\nдумать, что Божество подобно золоту, или серебру, или\nкамню,\nносящим\nпечать\nискусства\nи\nмысли\nчеловеческой,","30":"Поэтому,\nоставив\nбез\nвнимания\nвремена\nневедения, Бог теперь возвещает людям, всем и всюду,\nчтобы они каялись,","31":"ибо Он определил день, когда будет судить\nвселенную по праведности, чрез Мужа, Которого Он\nпоставил, дав удостоверение всем, воскресив Его из\nмертвых.","32":"Услышав же о воскресении мертвых, одни\nнасмехались, другие сказали: мы послушаем тебя об\nэтом еще раз.","33":"Так Павел вышел из среды их.","34":"Но некоторые люди, примкнув к нему, уверовали:\nмежду ними и Дионисий Ареопагит и женщина, по\nимени Дамарь, и другие с ними."},"18":{"1":"После этого, удалившись из Афин, он пришел в\nКоринф.","2":"И\nнайдя\nнекоего\nИудея,\nпо\nимени\nАкилу,\nПонтянина родом, недавно прибывшего из Италии, и\nПрискиллу, жену его, – потому что Клавдий повелел\nвсем Иудеям удалиться из Рима, – пришел к ним,","3":"и так как он был того же ремесла, то остался у\nних, и они работали: были они по ремеслу делатели\nпалаток.","4":"И говорил он в синагоге каждую субботу и\nубеждал как Иудеев, так и Еллинов.","5":"Когда же пришли из Македонии Сила и Тимофей,\nПавел всецело отдался слову, свидетельствуя Иудеям,\nчто Иисус есть Христос.","6":"Но так как они противились и хулили, то он,\nотряхнув одежды, сказал им: кровь ваша на голове\nвашей. Чист я. Отныне иду к язычникам.","7":"И уйдя оттуда, он пришел в дом человека по\nимени Тития Иуста, чтущего Бога, дом которого был\nсмежный с синагогой.","8":"А Крисп, начальник синагоги, уверовал в Господа\nсо всем домом своим, и многие из Коринфян, слыша,\nверовали и крестились.","9":"И сказал Господь ночью в видении Павлу: не\nбойся, но говори и не умолкай,","10":"потому что Я с тобою, и никто к тебе не\nподступится, чтобы причинить тебе зло, потому что\nмного у Меня народа в этом городе.","11":"И он остался год и шесть месяцев, уча среди них\nслову Божию.","12":"А когда Галлион был проконсулом Ахаии, Иудеи\nподнялись единодушно против Павла и привели его в\nсуд,","13":"говоря, что он убеждает людей чтить Бога не по\nЗакону.","14":"Когда же Павел собирался открыть уста, сказал\nГаллион Иудеям: если бы было какое преступление или\nзлодеяние, о Иудеи! – я бы с достаточным основанием\nпринял вашу жалобу.","15":"Но если спор идет о слове и об именах и о вашем\nзаконе, смотрите сами: в этом я не хочу быть судьей.","16":"И он прогнал их из суда.","17":"И все, схватив Сосфена, начальника синагоги,\nбили его перед судом, и Галлиону не было до этого\nникакого дела.","18":"А Павел, пробыв еще немало дней, простился с\nбратьями и отплыл в Сирию, и с ним Прискилла и Акила,\nостригши себе в Кенхреях голову; ибо имел он на себе\nобет.","19":"Достигли они Ефеса, и оставил он их там, сам же,\nвойдя в синагогу, имел беседу с Иудеями.","20":"И хотя они просили его остаться на более\nпродолжительное время, он не согласился,","21":"но простился и, сказав: [мне нужно непременно\nсовершить наступающий праздник в Иерусалиме;] я\nснова возвращусь к вам, если Богу угодно, – отплыл из\nЕфеса","22":"и, высадившись в Кесарии, поднялся в Иерусалим\nи, приветствовав церковь, сошел в Антиохию.","23":"Проведя там некоторое время, он отправился в\nпуть, проходя по порядку Галатийскую страну и\nФригию, утверждая всех учеников.","24":"Иудей\nнекий,\nпо\nимени\nАполлос,\nродом\nАлександриец, муж красноречивый, прибыл в Ефес. Он\nбыл силен в Писаниях.","25":"Был он наставлен пути Господню и, пламенея\nдухом, говорил и учил об Иисусе точно, зная только\nкрещение Иоанново.","26":"Он начал с дерзновением говорить в синагоге.\nУслышав его, Прискилла и Акила приняли его и еще\nточнее изложили ему путь Божий.","27":"А когда он хотел пройти в Ахаию, то братья, в\nпоощрение ему, написали ученикам, чтобы его приняли.\nПрибыв,\nон\nмного\nсодействовал\nуверовавшим\nблагодатию:","28":"ибо он с большой силой всенародно опровергал\nИудеев, доказывая Писаниями, что Иисус есть Христос."},"19":{"1":"И было, что в то время, как Аполлос был в\nКоринфе, Павел, пройдя горные области, пришел в Ефес\nи нашел неких учеников.","2":"И он сказал им: приняли ли вы Духа Святого, когда\nуверовали? А они ему: мы даже и не слышали, есть ли\nДух Святой,","3":"А он сказал: во что же вы были крещены? Они\nсказали: в крещение Иоанново.","4":"И сказал Павел: Иоанн крестил крещением\nпокаяния, говоря народу, чтобы веровали в Грядущего\nпо нем, то есть в Иисуса.","5":"И услышали они, и были крещены во имя Господа\nИисуса.","6":"И когда Павел возложил на них руки, пришел на\nних Дух Святой, и они начали говорить языками и\nпророчествовать.","7":"Было их всех человек около двенадцати.","8":"И войдя в синагогу, он дерзновенно проповедовал\nв течение трех месяцев, споря и убеждая о Царстве\nБожием.","9":"Но когда некоторые начали ожесточаться и не\nверить, злословя этот Путь перед собранием, то он,\nотстав от них, отделил учеников и каждый день вел\nбеседы в училище Тиранна.","10":"Так было в течение двух лет, так что все\nнаселяющие Асию услышали слово Господне, как Иудеи,\nтак и Еллины.","11":"Силы же необычайные Бог творил руками Павла,","12":"так что и на больных переносили с тела его\nплатки и опоясания, и их покидали болезни, и злые духи\nвыходили.","13":"А\nнекоторые\nи\nиз\nбродячих\nИудейских\nзаклинателей попытались призывать над имеющими\nзлых духов имя Господа Иисуса, говоря: заклинаю вас\nИисусом, Которого проповедует Павел.","14":"Делали это семь сыновей некоего Скевы,\nИудейского первосвященника.","15":"Но злой дух сказал им в ответ: Иисуса я знаю, и\nПавел мне знаком, а вы кто?","16":"И бросился на них человек, в котором был злой\nдух, одолел их всех, и взял над ними такую силу, что\nони нагие и израненные, выбежали из того дома.","17":"Это\nсделалось\nизвестным\nвсем\nИудеям\nи\nЕллинам, живущим в Ефесе, и напал страх на всех их, и\nвеличаемо было имя Господа Иисуса.","18":"И многие из уверовавших приходили, исповедуя\nи объявляя дела свои.","19":"А из занимавшихся колдовством довольно многие\nснесли в кучу свои книги и жгли перед всеми; и\nподсчитали их цены, и оказалось пятьдесят тысяч\nсеребром.","20":"С такой силой Господне слово возрастало и\nукреплялось.","21":"Когда это совершилось, Павел положил в духе,\nпройдя Македонию и Ахаию, идти в Иерусалим, говоря:\nпобывав там, надо мне видеть и Рим.","22":"И послав в Македонию двоих из служивших ему,\nТимофея и Ераста, сам остался на время в Асии.","23":"Произошел в то время мятеж немалый из-за\nПути.","24":"Ибо некто, по имени Димитрий, серебряных дел\nмастер,\nделавший\nсеребряные\nхрамы\nАртемиды,\nдоставлял художникам немалый заработок.","25":"Собрав их и работников, занятых таким же\nделом, он сказал: люди, вы знаете, что от этого\nзаработка зависит наше благосостояние.","26":"И вы видите и слышите, что не только в Ефесе,\nно почти во всей Асии Павел этот своими внушениями\nсовратил немало народа, говоря, что делаемое руками –\nне боги.","27":"И опасность для нас не только в том, что это\nремесло станет презренным, но что и святилище\nвеликой богини Артемиды будет считаться ни во что, и\nокажется лишенной своего величия и та, которую\nпочитает вся Асия и вселенная.","28":"Услышав это и исполнившись ярости, они начали\nкричать: велика Артемида Ефесская!","29":"И город исполнился смятением, и все, как один,\nустремились в театр, потащив с собой Гайя и Аристарха,\nМакедонян, спутников Павла.","30":"Когда же Павел хотел войти в толпу, ученики его\nне пускали.","31":"Некоторые же и из асиархов, будучи ему\nдрузьями, послали просить его не ходить в театр.","32":"Итак, одни кричали одно, другие другое; ибо\nсобрание было беспорядочное, и большинство не знало,\nчего ради они собрались.","33":"Тогда\nвыдвинули\nиз\nтолпы\nАлександра,\nвыставленного Иудеями. И Александр, дав знак рукой,\nхотел защищаться перед народом.","34":"Когда же узнали, что он Иудей, то все в один\nголос закричали, и около двух часов кричали: велика\nАртемида Ефесская!","35":"Тогда грамматевс, успокоив толпу, сказал: мужи\nЕфесяне, кто из людей не знает, что город Ефес есть\nстраж великой Артемиды и с неба упавшего образа?","36":"Итак, раз это непререкаемо, надо вам быть\nспокойными и ничего сгоряча не делать.","37":"Ибо привели вы этих мужей, не виновных ни в\nкощунстве, ни в хуле на нашу богиню.","38":"Итак, если Димитрий и другие с ним художники\nимеют на кого-нибудь жалобу, – то суды действуют, и\nесть проконсулы: пусть приносят жалобы друг на друга.","39":"Если же вы ищете чего-нибудь еще, то это будет\nрешено в законном собрании.","40":"Ибо мы не сможем оправдаться в этом сборище и\nподвергаемся опасности быть обвиненными в восстании\nза то, что без всякого основания произошло сегодня. И\nсказав это, он распустил собрание."},"20":{"1":"По\nпрекращении\nмятежа\nПавел,\nпослав\nза\nучениками\nи\nдав\nим\nнаставления,\nпростился\nи\nотправился в Македонию.","2":"Пройдя же эту область и наставив их обильным\nсловом, пришел в Елладу","3":"и, проведя там три месяца, решил возвращаться\nчерез Македонию, потому что Иудеи готовили на него\nпокушение во время предстоявшего ему морского пути\nв Сирию.","4":"Сопровождали его Сосипатр Пирров Вериянин, а\nиз\nФессалоникийцев\nАристарх\nи\nСекунд,\nи\nГаий\nДервянин и Тимофей, Асийцы же – Тихик и Трофим.","5":"Они пройдя вперед, ожидали нас в Троаде.","6":"Мы же отплыли после дней Опресноков из Филипп\nи в пять дней прибыли к ним в Троаду, где провели семь\nдней.","7":"В первый же день недели, когда мы были собраны\nдля преломления хлеба, Павел беседовал с ними,\nнамереваясь отправиться в путь на следующий день, и\nпродолжил слово до полуночи.","8":"Было достаточно светильников в горнице, где мы\nбыли собраны.","9":"Сидел в окне некий юноша, по имени Евтих,\nпогружаясь\nв\nглубокий\nсон\nпо\nмере\nтого,\nкак\nзатягивалась беседа Павла. Погруженный в сон, он упал\nс третьего этажа и был поднят мертвым.","10":"Павел, спустившись, лег на него всем телом и\nсказал: не смущайтесь, ибо душа его в нем.","11":"Поднявшись наверх и преломив хлеб и вкусив, и\nеще немало побеседовав до зари, отправился в путь.","12":"Между тем отрока привели живого, и были они\nутешены безмерно.","13":"А мы пошли вперед на корабль и отплыли в Асс с\nнамерением взять оттуда Павла: ибо он так приказал,\nнамереваясь сам идти сухим путем.","14":"Когда же он встретился с нами в Ассе, мы, взяв\nего, прибыли в Митилину;","15":"отплыв оттуда, на следующий день поравнялись\nс Хиосом, а на другой день дошли до Самоса и днем\nпозже пришли в Милет.","16":"Ибо Павел рассудил проплыть мимо Ефеса, чтобы\nне получилось у него потери времени в Асии; ибо он\nспешил, если бы это было для него возможно, в день\nПятидесятницы быть в Иерусалиме.","17":"Из Милета он послал в Ефес и вызвал к себе\nпресвитеров церкви.","18":"И когда они прибыли к нему, он сказал им: вы\nзнаете, как я с первого дня, когда пришел в Асию, все\nвремя с вами жил,","19":"работая\nдля\nГоспода\nсо\nвсяким\nсмиренномудрием\nи\nслезами\nи\nсреди\nискушений,\nпостигших меня по козням Иудеев;","20":"что я не опустил ничего полезного: проповедал\nвам и учил вас всенародно и по домам,","21":"свидетельствуя, как Иудеям, так и Еллинам о\nпокаянии пред Богом и о вере в Господа нашего Иисуса\nХриста.","22":"И вот теперь, связанный Духом, я иду в\nИерусалим, не зная, что мне там встретится,","23":"кроме того, что Дух Святой по всем городам\nсвидетельствует мне, говоря, что ждут меня узы и\nскорби.","24":"Но жизнь моя не имеет для меня никакой цены,\nтолько бы совершить поприще мое и служение, которое\nя принял от Господа Иисуса, засвидетельствовать\nЕвангелие благодати Божией.","25":"И теперь, вот, я знаю, что больше не увидите\nлица\nмоего\nвы\nвсе,\nмежду\nкоторыми\nя\nходил,\nпроповедуя Царство.","26":"Поэтому свидетельствую вам в сегодняшний\nдень, что чист я от крови всех;","27":"ибо я не опустил возвестить вам весь совет\nБожий.","28":"Блюдите себя и всё стадо, в котором Дух Святой\nпоставил\nвас\nепископами\nпасти\nЦерковь\nБожию,\nкоторую Он приобрел Себе кровию Своею.","29":"Я знаю, что по отшествии моем войдут к вам\nволки лютые, не щадящие стада,","30":"и из вас самих восстанут люди, говорящие\nпревратное, чтобы увлечь учеников за собой.","31":"Поэтому бодрствуйте, помня, что я три года\nночью и днем не переставал со слезами вразумлять\nкаждого особо.","32":"И теперь вверяю вас Богу и слову благодати Его,\nмогущему устроить и дать наследие вместе со всеми\nосвященными.","33":"Серебра или золота или одежды я ни от кого не\nпожелал.","34":"Вы сами знаете, что нуждам моим и тех, кто\nбыли со мной, послужили эти руки.","35":"Во всём показал я вам, что так трудясь, надо\nподдерживать слабых и помнить слова Господа Иисуса,\nибо\nОн\nСам\nсказал:\n«блаженнее\nдавать,\nчем\nпринимать».","36":"Сказав это, он преклонил колени свои и со всеми\nими помолился.","37":"И был немалый плач у всех и, бросаясь на шею\nПавлу, целовали его,","38":"скорбя особенно о слове, которое он сказал, что\nне придется им больше видеть лица его. И провожали\nего на корабль."},"21":{"1":"Когда же мы, оторвавшись от них, отплыли, то\nпришли прямым путем в Кос, а на следующий день в\nРодос, и оттуда в Патару;","2":"и найдя корабль, идущий в Финикию, сели на него\nи отплыли,","3":"Оказавшись в виду Кипра, и оставив его слева, мы\nплыли в Сирию и пристали в Тире; ибо там корабль\nвыгружал товар.","4":"И найдя учеников, мы остались там семь дней.\nОни Духом говорили Павлу не ходить в Иерусалим.","5":"И было: когда окончились для нас эти дни, мы\nвышли и отправились, и все с жёнами и детьми\nпровожали нас за городскую черту, и на берегу,\nпреклонив колени, мы, помолясь,","6":"расстались друг с другом. И сели мы на корабль, а\nте вернулись к себе.","7":"Мы же, окончив плавание, прибыли из Тира в\nПтолемаиду и, приветствовав братьев, пробыли у них\nодин день.","8":"А на другой день, отправившись, мы пришли в\nКесарию и, войдя в дом Филиппа, благовестника, одного\nиз семи, остались у него.","9":"Были\nу\nнего\nчетыре\nдочери\n–\nдевы\nпророчествующие.","10":"Мы задержались там на много дней. Тем\nвременем пришел из Иудеи некий пророк, по имени\nАгав,","11":"и войдя к нам и взяв пояс Павла, связал себе\nноги и руки и сказал: так говорит Дух Святой: «мужа,\nкому принадлежит этот пояс, так свяжут в Иерусалиме\nИудеи и предадут в руки язычников».","12":"Когда мы услышали это, то начали просить, как\nмы так и местные, чтобы он не ходил в Иерусалим.","13":"Тогда ответил Павел: что вы делаете, плача и\nсокрушая мое сердце? Ведь я готов не только быть\nсвязанным, но и умереть в Иерусалиме за имя Господа\nИисуса.","14":"И так как он не поддавался уговорам, мы\nумолкли, сказав: да будет воля Господня.","15":"После этих дней мы, собравшись, пошли в\nИерусалим.","16":"Пошли с нами из Кесарии и некоторые из\nучеников, ведя нас к некоему Мнасону, Кипрянину,\nдавнему ученику, чтобы у него остановиться.","17":"По прибытии нашем в Иерусалим, братья\nприняли нас с радостью.","18":"На следующий день Павел вместе с нами\nотправился к Иакову, и пресвитеры пришли все.","19":"И приветствовав их, он начал излагать в\nподробностях, что сотворил Бог среди язычников чрез\nслужение его.","20":"Они, выслушав, прославляли Бога и сказали ему:\nвидишь, брат, какое множество уверовавших среди\nИудеев, и все они ревнители Закона.","21":"О тебе же они наслышались, что ты всех Иудеев,\nживущих между язычниками, учишь отступлению от\nМоисея, чтобы они не обрезывали детей и не поступали\nпо обычаям.","22":"Итак, что же? Конечно, надо предвидеть, что\nсоберется толпа, ибо они услышат, что ты пришел.","23":"Сделай же, что мы тебе скажем. Есть у нас\nчетыре человека, имеющих на себе обет.","24":"Взяв их, очистись с ними и прими на себя\nиздержки за них, чтобы они обрили себе голову, и\nузнают все, что ничего того нет, чего они наслышались\nо тебе, но что ты и сам продолжаешь соблюдать Закон.","25":"А об уверовавших язычниках мы написали,\nрассудив, чтобы они хранили себя от идоложертвенного\nи крови и удавленины и блуда.","26":"Тогда, взяв этих людей, Павел на другой день,\nочистившись с ними, вошел в храм, объявляя окончание\nдней очищения, когда за каждого из них будет сделано\nприношение.","27":"Когда же семь дней кончались, Асийские Иудеи,\nувидев его в храме, возмутили всю толпу и наложили на\nнего руки,","28":"крича: мужи Израильские, на помощь! Это –\nчеловек, который всех и повсюду учит против народа и\nЗакона и места этого, да еще Еллинов ввел в храм и\nосквернил святое место это.","29":"Ибо они перед тем увидели Трофима Ефесянина\nв городе вместе с ним: они думали, что Павел ввел его в\nхрам.","30":"И пришел в движение весь город, и сбежался\nнарод, и схватив Павла, повлекли его вон из храма, и\nтотчас затворены были двери.","31":"Они хотели его убить, и дошло сообщение до\nтрибуна когорты, что весь Иерусалим охвачен смутой.","32":"Он тотчас, взяв воинов и сотников, устремился на\nних: увидев трибуна и воинов, они перестали бить\nПавла.","33":"Тогда трибун приблизился, взял его и приказал\nсвязать двумя цепями, и спрашивал, кто он и что\nсделал.","34":"В толпе один выкрикивал одно, другие – другое;\nи так как из-за шума он не мог ничего узнать в\nточности, то приказал вести его в казарму.","35":"Когда же он оказался на лестнице, воинам\nпришлось его нести из-за напора толпы;","36":"ибо множество народа шло следом, крича:\nсмерть ему!","37":"При входе в казарму Павел говорит трибуну:\nможно ли мне сказать тебе кое-что? А тот сказал: ты\nзнаешь по-гречески?","38":"Так, значит, ты не тот Египтянин, который\nнедавно возмутил и вывел в пустыню четыре тысячи\nчеловек из сикариев?","39":"И сказал Павел: человек я – Иудей, Тарсянин,\nгражданин немаловажного Киликийского города. А тебя\nпрошу, позволь мне говорить к народу.","40":"Тот позволил. Павел, стоя на лестнице, сделал\nрукой знак народу; и когда установилось глубокое\nмолчание, он обратился к ним на еврейском языке,\nговоря:"},"22":{"1":"Мужи братья и отцы, выслушайте мою нынешнюю\nперед вами защиту.","2":"Услышав, что он начал свое обращение к ним на\nеврейском языке, они стали еще тише.","3":"И он сказал: я – Иудей, рожденный в Тарсе\nКиликийском, но воспитанный в этом городе, у ног\nГамалиила, наставленный во всей точности отеческого\nЗакона, ревнитель по Боге, как все вы сегодня.","4":"На этот Путь я воздвигнул смертельное гонение,\nзаключая в узы и предавая в тюрьмы как мужчин, так и\nженщин,","5":"в чем и первосвященник мне свидетель и весь\nсовет старейшин; получив от них и письма к братьям, я\nшел в Дамаск с тем, чтобы и там находящихся привести\nв узах в Иерусалим для наказания.","6":"И было со мной, когда я шел и приближался к\nДамаску: около полудня внезапно воссиял с неба\nсильный свет вокруг меня,","7":"и я упал на землю и услышал голос, говорящий\nмне: «Савл, Савл, что ты Меня гонишь?»","8":"И я ответил: «кто Ты, Господи?» И Он сказал мне:\n«Я – Иисус Назорей, Которого ты гонишь».","9":"Бывшие со мной свет видели, но голоса Того, Кто\nмне говорил, не слышали.","10":"И я сказал: «что мне делать, Господи?» Господь\nже сказал мне: «встань и иди в Дамаск и там тебе будет\nсказано о всём, что назначено тебе делать»,","11":"И пока я ничего не видел от славы света того,\nбывшие со мной за руку привели меня в Дамаск.","12":"А некий Анания, муж благочестивый по Закону,\nимеющий\nдоброе\nсвидетельство\nот\nвсех\nместных\nИудеев,","13":"пришел ко мне и, подойдя, сказал мне: «Савл,\nбрат, прозри!» И я в тот же час прозрел и устремил взор\nна него.","14":"А он сказал: «Бог отцов наших предназначил\nтебя познать волю Его и увидеть Праведного и\nуслышать голос из уст Его,","15":"потому что ты будешь свидетелем Ему пред\nвсеми людьми о том, что ты видел и слышал.","16":"И теперь, что ты медлишь? Восстав, крестись и\nсмой грехи твои, призвав имя Его».","17":"И было со мной по возвращении в Иерусалим,\nкогда я молился в храме: пришел я в исступление","18":"и увидел Его, и Он говорил мне: «поспеши и\nвыйди скорее из Иерусалима, потому что не примут\nтвоего свидетельства о Мне».","19":"Я сказал: «Господи, они знают, что я заключал в\nтюрьмы и бил в синагогах верующих в Тебя;","20":"и когда проливалась кровь Стефана, свидетеля\nТвоего, я и сам стоял тут же и сочувствовал и стерег\nодежды убивавших его».","21":"И Он сказал мне: «иди, потому что Я пошлю тебя\nдалеко к язычникам».","22":"До этого слова они его слушали, а тогда\nвозвысили голос свой, говоря: долой с земли такого!\nНельзя ему жить!","23":"И пока они кричали и потрясали одеждами и\nбросали пыль в воздух,","24":"трибун велел ввести его в казарму, сказав\nподвергнуть его допросу под бичом, чтобы узнать, по\nкакой причине они так кричали на него.","25":"Когда же растянули его для бичевания, Павел\nсказал присутствовавшему сотнику: можно ли вам\nбичевать\nчеловека,\nРимского\nгражданина,\nи\nне\nосужденного?","26":"Услышав это, сотник явился к трибуну и доложил\nему: что ты собираешься делать? Ведь человек этот\nРимский гражданин.","27":"Тогда трибун подошел и сказал ему: скажи мне,\nты Римский гражданин? Он сказал: да.","28":"И трибун ответил: я за большие деньги приобрел\nэто гражданство. Павел же сказал: а я и родился\nгражданином.","29":"И тотчас же отступили от него собиравшиеся его\nпытать, а трибун испугался, узнав, что Павел Римский\nгражданин, а он связал его.","30":"На другой день, желая узнать точно, в чем\nобвиняют его Иудеи, он освободил его от уз и велел\nсобраться первосвященникам и всему синедриону и,\nприведя Павла, поставил его перед ними."},"23":{"1":"Устремив взор на синедрион, Павел сказал: мужи\nбратья, я по всей доброй совести прожил жизнь мою\nпред Богом до сего дня.","2":"Но первосвященник Анания приказал стоящим при\nнем бить его по устам,","3":"Тогда Павел ему сказал: бить тебя будет Бог,\nстена побеленная! И сидишь-то ты, чтобы судить меня\nпо Закону, и преступая Закон, велишь меня бить!","4":"Стоящие же сказали: первосвященника Божия\nпоносишь?","5":"И сказал Павел: я не знал, братья, что он\nпервосвященник. Ибо написано: «о начальствующем в\nнароде твоем не говори худо».","6":"Но учтя, что одна часть принадлежит к саддукеям,\nа другая к фарисеям, Павел начал громко говорить в\nсинедрионе: мужи братья, я фарисей, сын фарисейский;\nсудят меня за надежду и за воскресение мертвых.","7":"Когда он сказал это, произошла распря между\nфарисеями и саддукеями, и собрание раскололось.","8":"Ибо саддукеи говорят, что нет ни воскресения, ни\nангела, ни духа; фарисеи же признают всё это.","9":"Поднялся большой крик и, встав, некоторые из\nкнижников\nфарисейской\nстороны\nспорили,\nговоря:\nничего худого мы не находим в этом человеке. А что,\nесли дух сказал ему, или ангел?","10":"Но так как распря усиливалась, то трибун,\nопасаясь, как бы они не растерзали Павла, приказал\nнаряду воинов придти, взять его силой из их среды и\nвести в казарму.","11":"А следующей ночью Господь, представ ему,\nсказал: мужайся; ибо как ты был свидетелем Моим в\nИерусалиме, так надлежит тебе свидетельствовать и в\nРиме.","12":"С наступлением дня, Иудеи сговорились между\nсобой и связали себя заклятием не есть и не пить,\nдоколе не убьют Павла.","13":"Было более сорока, составивших этот заговор.","14":"Они,\nявившись\nк\nпервосвященникам\nи\nстарейшинам, сказали: мы заклятием закляли себя\nничего не вкушать, доколе не убьем Павла.","15":"Итак, теперь же вы с синедрионом дайте знать\nтрибуну, чтобы он привел его к вам, якобы для более\nточного рассмотрения его дела; а мы, прежде чем он\nприблизится, готовы убить его.","16":"Услышав же об этой западне, сын сестры\nПавловой пришел и, войдя в казарму, сообщил Павлу.","17":"Призвав одного из сотников, Павел сказал:\nотведи этого юношу к трибуну, потому что он имеет\nнечто сказать ему.","18":"Тот, взяв его, привел к трибуну и говорит: узник\nПавел, призвав меня, попросил привести к тебе этого\nюношу, который имеет нечто сказать тебе.","19":"Трибун, взяв его за руку и отведя в сторону,\nспрашивал: что такое имеешь ты сообщить мне?","20":"Он сказал: Иудеи согласились просить тебя,\nчтобы завтра ты привел Павла в синедрион, якобы для\nболее точного расследования о нем.","21":"Ты же не дай им убедить тебя: ибо его\nподстерегают более сорока человек из них, которые\nсвязали себя заклятием не есть и не пить, доколе не\nубьют его; и они теперь готовы, ожидая твоего\nраспоряжения.","22":"Тогда трибун отпустил юношу, приказав никому\nне\nвыдать,\nчто\n«ты\nменя\nпоставил\nоб\nэтом\nв\nизвестность».","23":"И призвав двух сотников, сказал: приготовьте\nдвести воинов, чтобы шли в Кесарию, и семьдесят\nконных и двести стрелков, с третьего часа ночи;","24":"и вьючных животных дать, чтобы, посадив Павла\nверхом, благополучно доставить к правителю Феликсу.","25":"И написал письмо такого содержания:","26":"«Клавдий Лисий Превосходнейшему Правителю\nФеликсу, – радоваться!","27":"Этого человека схватили Иудеи и собирались\nубить. Придя с нарядом воинов, я его выручил, получив\nсведения, что он Римский гражданин.","28":"И желая точно узнать то обвинение, которое они\nвыставляют против него, я привел его в их синедрион,","29":"и нашел, что относится оно к спорным вопросам\nих закона, но что он не обвиняется ни в каком\nпреступлении достойном смерти или уз.","30":"Между тем, будучи осведомлен о готовящемся на\nэтого человека покушении, я тотчас же послал его к\nтебе, приказав и обвинителям говорить против него\nперед тобой. Будь здоров».","31":"Итак, воины, по данному им приказанию, взяв\nПавла, повели его ночью в Антипатриду.","32":"А на другой день, предоставив конным идти с\nним, возвратились в казарму.","33":"Те,\nприбыв\nв\nКесарию\nи\nвручив\nписьмо\nправителю, представили ему и Павла.","34":"Прочитав же и спросив, из какой он провинции, и\nузнав, что из Киликии,","35":"правитель сказал: я выслушаю тебя, когда явятся\nи твои обвинители, повелев ему быть под стражей в\nИродовой претории."},"24":{"1":"А через пять дней прибыл первосвященник Анания\nс некоторыми старейшинами и поверенным в делах,\nнеким Тертуллом, которые заявили правителю жалобу\nна Павла.","2":"Когда же он был позван, начал Тертулл обвинять,\nговоря: пользуясь, благодаря тебе, глубоким миром и\nпреобразованиями на пользу этого народа, вследствие\nтвоего попечения, –","3":"мы их принимаем, Превосходнейший Феликс, во\nвсем и повсюду со всяческой признательностью.","4":"Но чтобы не утруждать тебя более, прошу тебя\nвыслушать\nнас\nкратко\nсо\nсвойственной\nтебе\nснисходительностью.","5":"Мы нашли этого человека заразой и возбудителем\nмятежа\nсреди\nвсех\nИудеев\nпо\nвселенной\nи\nпредводителем Назорейской ереси.","6":"Он сделал попытку и храм осквернить, его мы и\nзадержали.","7":"Отрывок 24.6–8: «и по нашему Закону хотели\nсудить его. Но пришел трибун Лисий и с великим\nнасилием вырвал его из наших рук, приказав и его\nобвинителям идти к тебе» (ср. прежние русские\nпереводы) отсутствует в древнейших рукописях Деян.","8":"От него ты сможешь сам, расследовав всё это,\nузнать то, в чем мы обвиняем его.","9":"Присоединились к обвинению и Иудеи, говоря, что\nэто так.","10":"И ответил Павел, когда правитель сделал ему\nзнак говорить: зная, что ты с давних лет судишь этот\nнарод, я с легким сердцем буду защищать мое дело,","11":"так как ты можешь узнать, что не более\nдвенадцати дней, как я пришел для поклонения в\nИерусалим.","12":"И не нашли меня ни в храме с кем-либо\nспорящим или вызывающим волнение народа, ни в\nсинагогах, ни в городе,","13":"и не могут доказать тебе того, в чем теперь\nобвиняют меня.","14":"Но в том я признаюсь тебе, что на Пути, который\nони называют ересью, я, действительно, служу Богу\nотцов наших, веруя всему, что согласно с Законом и что\nнаписано у Пророков,","15":"надежду имея на Бога, которую и сами они\nразделяют, – что будет воскресение и праведных и\nнеправедных.","16":"Потому\nя\nи\nсам\nстараюсь\nвсегда\nиметь\nнепорочную совесть пред Богом и людьми.","17":"Через несколько лет я прибыл с целью передать\nмилостыни народу моему и приношения.","18":"При этом нашли меня очистившимся в храме, не с\nтолпой и не с шумом,","19":"нашли же какие-то Иудеи из Асии, которым\nнадлежало бы быть здесь у тебя и обвинять, если бы у\nних было что против меня.","20":"Или пусть они сами скажут, какое нашли они\nпреступление, когда я предстал пред синедрионом,","21":"кроме одного этого слова, которое я возгласил,\nстоя между ними: «за воскресение мертвых вы меня\nсудите сегодня».","22":"Но Феликс, имея более точные сведения о Пути,\nотослал их для дополнительного расследования, сказав:\nкогда придет трибун Лисий, я рассмотрю ваше дело;","23":"и дал распоряжение сотнику держать его под\nстражей, но давать ему некоторые послабления, и не\nпрепятствовать никому из близких его служить ему.","24":"Несколько дней спустя, Феликс, прибыв с\nДрузиллой, женой своей. Иудеянкой, послал за Павлом\nи слушал его о вере во Христа Иисуса.","25":"Но так как он говорил о праведности и\nобладании собой и о будущем суде, то Феликс, придя в\nстрах, ответил: пока иди, а при случае я тебя вызову к\nсебе.","26":"В то же время он и надеялся, что Павел даст ему\nденег. Потому-то, часто за ним посылая, он и беседовал\nс ним.","27":"Но по прошествии двух лет, Феликса сменил\nПоркий Фест. Желая сделать угодное Иудеям, Феликс\nоставил Павла в узах."},"25":{"1":"Итак, Фест, вступив в должность правителя, через\nтри дня отправился из Кесарии в Иерусалим,","2":"и заявили ему первосвященники и первые люди\nИудейские жалобу на Павла и ходатайствовали перед\nним,","3":"испрашивая себе как милость против него, чтобы\nвызвал его в Иерусалим, готовя западню с целью убить\nего в пути.","4":"Фест ответил, что Павел содержится под стражей\nв Кесарии, и что ему самому скоро предстоит отбыть\nтуда.","5":"Итак, те между вами, сказал он, которые могут,\nпусть отправятся вместе со мной, и если есть что в этом\nчеловеке предосудительного, пусть обвиняют его.","6":"Пробыв между ними не больше восьми или десяти\nдней, он отправился в Кесарию, и на другой же день,\nсев на судейское место, велел привести Павла.","7":"И когда он прибыл, стали вокруг него пришедшие\nиз Иерусалима Иудеи, выставляя многие и тяжкие\nобвинения, которых они не в силах были доказать,","8":"тогда как Павел говорил в свою защиту: я ни в чем\nне погрешил ни против Закона Иудейского, ни против\nхрама, ни против Кесаря.","9":"Фест, желая сделать угодное Иудеям, сказал в\nответ Павлу: хочешь пойти в Иерусалим, чтобы там был\nтебе вынесен приговор по этим обвинениям в моем\nприсутствии?","10":"Но Павел сказал: я стою пред судом Кесаря, где\nмне надлежит быть судимым. Иудеям я не сделал\nникакого зла, как и ты превосходно знаешь.","11":"Итак, если я неправ и сделал что-либо достойное\nсмерти, я не отказываюсь умереть; если же ничего того\nнет, в чем они обвиняют меня, никто меня не может\nвыдать им в угоду. Требую суда Кесаря.","12":"Тогда Фест, обсудив с советом, ответил: ты\nпотребовал суда Кесаря, к Кесарю отправишься.","13":"По прошествии нескольких дней, царь Агриппа и\nВереника прибыли в Кесарию и приветствовали Феста.","14":"А так как они оставались там несколько дней,\nФест доложил царю дело Павла, говоря: человек некий\nоставлен Феликсом в узах,","15":"на которого, по прибытии моем в Иерусалим,\nзаявили\nжалобу\nпервосвященники\nи\nстарейшины\nИудейские, требуя его осуждения.","16":"Я им ответил, что нет обычая у Римлян выдавать\nкакого-либо человека, прежде чем обвиняемый не будет\nпоставлен лицом к лицу с обвинителями и не получит\nвозможность защищаться в том, в чем его обвиняют.","17":"Итак, когда они вместе со мной пришли сюда, я\nбез всякого отлагательства, на другой же день, сев на\nсудейское место, велел привести этого человека.","18":"Обступив его, обвинители не выставили никакого\nобвинения в тех злых делах, которые я предполагал;","19":"но они имели с ним какие-то споры о их\nсобственном\nбогопочитании\nи\nо\nкаком-то\nИисусе\nумершем, о Котором Павел утверждал, что Он жив.","20":"Недоумевая, как об этом вести расследование, я\nсказал, не хочет ли он идти в Иерусалим и там быть\nсудимым в этом.","21":"Но так как Павел потребовал, чтобы его оставили\nна решение Августа, я велел держать его под стражей,\nпока не препровожу его к Кесарю.","22":"Агриппа же сказал Фесту: я хотел бы и сам\nпослушать этого человека. И тот сказал: завтра же\nуслышишь его.","23":"На другой день, когда пришел Агриппа и\nВереника с большой пышностью и вошли в палату\nвместе с трибунами и виднейшими в городе людьми, и\nкогда Фест повелел, был приведен Павел.","24":"И\nговорит\nФест:\nцарь\nАгриппа\nи\nвсе\nприсутствующие с нами мужи, вы видите того, из-за\nкоторого всё множество Иудеев приступало ко мне и в\nИерусалиме и здесь с криком, что не должен он больше\nжить.","25":"Но я понял, что он ничего достойного смерти не\nсделал, а так как он сам потребовал суда Августа, я\nрешил послать его.","26":"Ничего верного написать о нем государю я не\nимею; поэтому я поставил его перед вами, и особенно\nперед тобой, царь Агриппа, чтобы, по расследовании,\nбыло мне что написать.","27":"Ибо мне кажется неразумным, посылая узника,\nне указать и предъявленных ему обвинений."},"26":{"1":"И сказал Агриппа Павлу: тебе разрешается\nговорить за себя. Тогда Павел, протянув руку, начал\nсвою защитительную речь:","2":"во всём, в чем обвиняют меня Иудеи, царь\nАгриппа, я почитаю себя счастливым защищаться\nсегодня перед тобой,","3":"потому особенно, что ты знаток всех обычаев и\nспорных мнений Иудеев. Поэтому прошу выслушать\nменя с долготерпением.","4":"Жизнь мою от юности, протекавшую с самого\nначала среди народа моего в Иерусалиме, ведают все\nИудеи,","5":"зная обо мне издавна если есть у них желание\nсвидетельствовать\n–\nчто\nжил\nя\nфарисеем,\nпо\nстрожайшему направлению в нашей вере.","6":"И теперь я стою перед судом за надежду на\nобещание, бывшее от Бога отцам нашим,","7":"исполнения которого надеются достичь наши\nдвенадцать колен, усердно служа Богу день и ночь. За\nэту надежду, царь, и обвиняют меня Иудеи.","8":"Почему у вас считается невероятным, что Бог\nвоздвигает мертвых?","9":"Ведь я и сам думал, что против имени Иисуса\nНазорея надо мне многое сделать.","10":"Это я и делал в Иерусалиме, и многих из святых я\nзаключил\nв\nтюрьмы,\nполучив\nвласть\nот\nпервосвященников, и когда их убивали, подавал свой\nголос против них;","11":"и по всем синагогам, многократно наказывая их,\nпринуждал к хуле и, в чрезмерной против них ярости,\nпреследовал их даже и в чужих городах.","12":"В этих условиях, отправляясь в Дамаск с\nполномочиями и поручением от первосвященников,","13":"я в полдень на дороге увидел, царь, свет с неба,\nсильнее солнечного блеска, осиявший меня и шедших\nсо мной.","14":"И когда все мы упали на землю, я услышал голос,\nговорящий мне на еврейском языке: «Савл, Савл, что ты\nменя гонишь? Трудно тебе идти против рожна».","15":"Я сказал: «Кто Ты, Господи?» Господь сказал: «Я\nИисус, Которого ты гонишь.","16":"Но встань и стань на ноги твои, ибо Я для того\nявился тебе, чтобы поставить тебя служителем и\nсвидетелем Моим, как ты Меня видел, и как Я явлюсь\nтебе,","17":"избавляя тебя от народа и от язычников, к\nкоторым Я посылаю тебя,","18":"открыть им глаза, чтобы обратились они от тьмы\nк свету и от власти сатаны к Богу, и чтобы получили они\nотпущение грехов и удел вместе с освященными, по\nвере в Меня».","19":"Поэтому,\nцарь\nАгриппа,\nя\nне\nоказал\nнепослушания небесному видению,","20":"но сперва находящимся в Дамаске и Иерусалиме,\nи по всей стране Иудейской, и язычникам возвещал,\nчтобы они каялись и обращались к Богу, творя дела,\nдостойные покаяния.","21":"За это Иудеи, задержав меня в храме, пытались\nрасправиться со мной.","22":"Итак, с помощью, которая приходит от Бога, я\nустоял до сего дня, свидетельствуя малому и великому,\nне говоря ничего, кроме того, о чем Пророки сказали и\nМоисей, что должно тому быть:","23":"Христу – пострадать и, воскресши первым из\nмертвых, свет возвещать народу и язычникам.","24":"Когда он так защищался, Фест громким голосом\nговорит: ты безумствуешь, Павел! Большая ученость\nдоводит тебя до безумия.","25":"А\nПавел\nговорит:\nя\nне\nбезумствую,\nПревосходнейший Фест, но возглашаю слова истины и\nздравого смысла.","26":"Ибо знает об этом царь, которому я и говорю с\nдерзновением. Ведь я не верю, чтобы сокрыто было от\nнего что-либо из этого; ибо не в углу это было\nсовершено.","27":"Веришь ли, царь Агриппа, Пророкам? Знаю, что\nверишь.","28":"Но Агриппа Павлу: еще немного, и ты будешь\nубеждать меня сделаться христианином.","29":"А Павел: молил бы я Бога, чтобы мало ли, много\nли, не только ты, но и все слушающие меня сегодня,\nсделались такими же как и я, кроме этих уз.","30":"И встал царь, и правитель, и Вереника, и\nсидевшие с ними,","31":"и удалившись, говорили между собой, что ничего\nдостойного смерти или уз человек этот не делает.","32":"Агриппа\nже\nсказал\nФесту:\nмог\nбы\nбыть\nосвобожден человек этот, если бы не потребовал суда\nКесаря."},"27":{"1":"Когда же решено было отплыть нам в Италию, то\nсдали и Павла и некоторых других узников сотнику, по\nимени Юлию, из когорты Августовой.","2":"Сев\nна\nАдрамитский\nкорабль,\nкоторому\nпредстояло плыть вдоль берегов Асии, мы отчалили. С\nнами был Аристарх, Македонянин из Фессалоники.","3":"И на другой день мы пристали в Сидоне; и Юлий,\nчеловеколюбиво обращаясь с Павлом, позволил ему\nпойти к друзьям и воспользоваться их усердием.","4":"И\nотправившись\nоттуда,\nмы\nплыли\nпод\nприкрытием Кипра, потому что ветры были противные;","5":"и переплыв море, омывающее берега Киликии и\nПамфилии, мы пристали в Мирах Ликийских.","6":"И там сотник, найдя Александрийский корабль,\nплывущий в Италию, посадил нас на него.","7":"Немало дней мы, медленно плывя, едва дошли до\nКнида. Так как ветер не позволял нам идти дальше, мы\nпошли под прикрытие Крита со стороны Салмоны,","8":"и с трудом, плывя вдоль Крита, пришли мы в\nнекое место, называемое Хорошие Пристани, близ\nкоторого был город Ласея.","9":"Но, так как протекло немало времени, и плавание\nбыло уже опасно, потому что и пост уже прошел, то\nПавел убеждал их,","10":"говоря им: мужи, я вижу, что плавание это будет\nс бедой и большим ущербом не только для груза и для\nкорабля, но и для нашей жизни.","11":"Но\nсотник\nбольше\nдоверял\nкормчему\nи\nначальнику корабля, нежели тому, что говорил Павел.","12":"А так как пристань не подходила для зимовки, то\nбольшинство было за то, чтобы сняться оттуда и, если\nбы было возможно добраться, перезимовать в Финике,\nпристани Критской, защищенной с юго-запада и с\nсеверо-запада.","13":"И когда подул легкий южный ветер, они,\nподумав, что получили желаемое, подняли якорь и\nпоплыли вдоль Крита, держась берега.","14":"Но\nвскоре\nобрушился\nна\nКрит\nветер,\nподнимающий смерчи, называемый Евракилон.","15":"И так как корабль захватило, и он не мог\nпротивиться, мы отдались ветру и нас носило.","16":"Пронесшись мимо некоего островка, называемого\nКлавда, мы едва оказались в силах справиться с лодкой.","17":"Подняв\nее,\nони\nпользовались\nканатами,\nобвязывая корабль. И опасаясь как бы не быть\nвыброшенными на Сирт, они спустили плавучий якорь и\nтак носились.","18":"И так как нас сильно било бурей, они на другой\nдень начали выбрасывать груз,","19":"и на третий день своими руками побросали\nоснастку корабля.","20":"И так как в течение ряда дней не показывались\nни солнце, ни звезды, и буря свирепствовала немалая, –\nв конце концов, стала пропадать у нас всякая надежда\nна спасение.","21":"Люди давно не ели. Тогда Павел, став посреди\nних, сказал: надо было, о мужи, послушавшись меня, не\nотходить от Крита и не терпеть этой беды и ущерба.","22":"И теперь призываю вас к бодрости, ибо ни одна\nдуша из вас не погибнет, а только корабль.","23":"Ибо ангел предстал мне этой ночью от Бога,\nКоторому я принадлежу, Которому и служу,","24":"и сказал: «не бойся, Павел; пред Кесарем должно\nтебе предстать, и вот даровал тебе Бог всех плывущих\nс тобой».","25":"Поэтому бодритесь, мужи: ибо я верю Богу, что\nбудет так, как мне сказано.","26":"Нам должно быть выброшенными на какой-то\nостров.","27":"А когда наступила четырнадцатая ночь, как мы\nносились по Адрии, около полуночи моряки стали\nдогадываться, что приближается к ним какая-то земля.","28":"И вымеряв глубину, нашли двадцать сажен;\nпотом, на небольшом расстоянии, вымеряв снова, нашли\nпятнадцать сажен.","29":"И опасаясь, как бы не попасть нам на скалы, они,\nбросив с кормы четыре якоря, напряженно ждали\nнаступления дня.","30":"Когда же моряки пытались бежать с корабля и\nспустили лодку на море под предлогом, что они якобы\nсобирались бросать якоря с носа,","31":"Павел сказал сотнику и воинам: если эти не\nостанутся на корабле, вы не можете спастись.","32":"Тогда воины отсекли канаты у лодки и дали ей\nупасть.","33":"А пока день еще не наступил, Павел призывал\nвсех принять пищу, говоря: четырнадцатый сегодня\nдень вы проводите в ожидании без пищи, ничего не\nвкусив;","34":"поэтому призываю вас принять пищу; это ведь\nнужно для вашего спасения; ибо ни у кого из вас волос\nс головы не пропадет.","35":"Сказав же это и взяв хлеб, он возблагодарил\nБога перед всеми и, преломив, начал есть.","36":"Все ободрились и тоже приняли пищу;","37":"было же всех нас на корабле двести семьдесят\nшесть душ.","38":"Насытившись\nпищей,\nони\nстали\nоблегчать\nкорабль, бросая пшеницу в море.","39":"А когда настал день, земли они не узнавали, но\nразличали какой-то залив с песчаным берегом, на\nкоторый и хотели, если бы могли, вывести корабль.","40":"И сняв якоря, они пустили их в море; вместе с\nтем, развязав веревки рулей и подняв передний парус\nпо ветру, держали к берегу.","41":"Попав же на песчаную отмель, они посадили на\nнее корабль. Нос увяз и остался недвижим, а корма\nразрушалась силою волн.","42":"Воины приняли было решение убить узников,\nчтобы кто-нибудь, выплыв, не убежал.","43":"Но\nсотник,\nжелая\nспасти\nПавла,\nвоспрепятствовал их намерению и велел умеющим\nплавать броситься и выходить на землю первыми,","44":"а остальным, кому – на досках, кому – на чем-\nнибудь от корабля; и так оказалось, что все спаслись на\nземлю."},"28":{"1":"И тогда, спасшись, мы узнали, что остров\nназывается Мелита.","2":"Туземцы стали проявлять к нам необычайное\nчеловеколюбие, ибо они, разведя костер, приняли всех\nнас, по случаю непрекращавшегося дождя и холода.","3":"Когда же Павел набрал некоторое количество\nхвороста и положил на костер, вышедшая от жара змея\nвпилась ему в руку.","4":"И когда увидели туземцы висящего на его руке\nгада, они говорили друг другу: конечно, убийца этот\nчеловек, которому, после того как он спасен был от\nморя, Правосудие не позволило жить.","5":"Но он, стряхнув гада в огонь, не потерпел\nникакого зла.","6":"Они же ожидали, что он распухнет или внезапно\nупадет мертвым. Но так как они ждали долго и видели,\nчто ничего дурного с ним не происходит, то, изменив\nсвое мнение, говорили, что он бог.","7":"В окрестностях того места были имения у\nначальника острова, по имени Публия, который, приняв\nнас, в течение трех дней оказывал нам дружеское\nгостеприимство.","8":"Было же, что отец Публия лежал одержимый\nлихорадкой и дизентерией. Павел, войдя к нему и\nпомолившись, возложил на него руки и исцелил его.","9":"Когда же это случилось, то прочие на острове,\nимевшие болезни, приходили и были исцеляемы.","10":"Они и почтили нас многими почестями и, при\nотъезде, дали нам на нужды.","11":"А\nчерез\nтри\nмесяца\nмы\nотплыли\nна\nперезимовавшем на острове Александрийском корабле,\nносившем имя Диоскуров.","12":"И пристав в Сиракузах, пробыли три дня,","13":"откуда, идя вдоль берега, достигли Ригия. И так\nкак через день поднялся южный ветер, мы прибыли на\nвторой день в Путеолы,","14":"где нашли братьев; они нас упросили остаться у\nних семь дней. И так мы пошли в Рим.","15":"И оттуда братья, услышав о нас, пошли к нам\nнавстречу до Аппиева Форума и Трех Таверн. Увидев их,\nПавел возблагодарил Бога и ободрился.","16":"Когда же вошли мы в Рим, Павлу позволено было\nжить особо со стерегущим его воином.","17":"Было же через три дня, что он созвал тех,\nкоторые были первыми среди Иудеев, и когда они\nсошлись, он начал говорить им: я, мужи братья, не\nсделав ничего против народа или отеческих обычаев,\nбыл, как узник, из Иерусалима предан в руки Римлян,","18":"которые, допросив меня, хотели отпустить,\nпотому что нет за мной никакой вины, заслуживающей\nсмерти.","19":"Но так как Иудеи возражали, я вынужден был\nпотребовать суда Кесаря, не с тем, чтобы обвинять в\nчем-либо народ мой.","20":"По этой-то причине я и призвал вас, чтобы\nувидеть вас и поговорить с вами; ибо за надежду\nИзраиля обложен я этой цепью.","21":"Они же сказали ему: мы никаких писем о тебе не\nполучили из Иудеи, и никто из братьев, придя, не\nвозвестил или не сказал чего-либо о тебе плохого.","22":"Но мы считаем уместным услышать от тебя, как\nты мыслишь; ибо об этом направлении нам известно,\nчто оно всюду вызывает споры.","23":"И назначив ему день, они пришли к нему на дом\nв большем числе, и он с утра до вечера говорил им,\nсвидетельствуя о Царстве Божием, и убеждая их об\nИисусе из Закона Моисеева и из Пророков.","24":"И одни убеждались тем, что говорилось, а другие\nне верили.","25":"Будучи же несогласны между собой, они стали\nуходить после того, как Павел сказал им одно слово:\nхорошо изрек Дух Святой чрез Исаию пророка отцам\nвашим, говоря:","26":"«Пойди к народу этому и скажи: Слухом будете\nслышать и не уразумеете, и глазами глядеть будете и\nне увидите;","27":"ибо ожирело сердце народа этого, и ушами они\nедва слышат, и глаза свои они закрыли, чтобы не\nувидеть глазами и ушами не услышать и сердцем не\nуразуметь и не обратиться. И Я исцелю их».","28":"Итак, да будет вам известно, что язычникам\nпослано это спасение Божие: они и услышат.","29":"Стих 29 прежних русских переводов: «Когда он\nсказал это, Иудеи ушли, много споря между собою»,\nотсутствует в древнейших рукописях Деян.","30":"И прожил Павел целых два года в нанятом им\nсамим помещении и принимал всех приходивших к\nнему,","31":"проповедуя Царство Божие и уча о Господе\nИисусе\nХристе\nсо\nвсяким\nдерзновением\nбеспрепятственно."}};
